fn add_mandatory_geometry_review_boundaries(draft: &mut WorkflowDraft) -> Result<()> {
    let commits = draft
        .nodes
        .iter()
        .filter(|node| node.kind == WorkflowNodeKind::Commit)
        .cloned()
        .collect::<Vec<_>>();
    for commit in commits {
        let base = format!("{}.geometry_review", commit.id);
        let mut review_id = base.clone();
        let mut suffix = 2_u32;
        while draft.nodes.iter().any(|node| node.id == review_id) {
            review_id = format!("{base}_{suffix}");
            suffix = suffix.saturating_add(1);
        }
        let ports = if commit.inputs.is_empty() {
            vec![annotagent_core::NodePort {
                id: "candidates".to_owned(),
                artifact_type: ArtifactKind::AnnotationCandidateSet,
                required: true,
                multiple: true,
            }]
        } else {
            commit.inputs.clone()
        };
        let mut review_parameters = BTreeMap::from([(
            "reason".to_owned(),
            serde_json::json!("geometry_verification_required"),
        )]);
        for key in ["task_id", "target_label"] {
            if let Some(value) = commit.parameters.get(key) {
                review_parameters.insert(key.to_owned(), value.clone());
            }
        }
        let review = annotagent_core::WorkflowDraftNode {
            id: review_id.clone(),
            node_type: "core.human_review".to_owned(),
            kind: WorkflowNodeKind::HumanReview,
            depends_on: commit.depends_on.clone(),
            inputs: ports.clone(),
            outputs: ports.clone(),
            model_binding: None,
            model_profile_binding: None,
            unresolved_model_requirement: None,
            required_skills: Vec::new(),
            validators: Vec::new(),
            refiners: Vec::new(),
            fallback: None,
            max_retries: 0,
            review_gate: true,
            parameters: review_parameters,
            retry_policy: RetryPolicy::default(),
            fallback_policy: annotagent_core::FallbackPolicy::default(),
            gate: ReviewGate {
                required: true,
                allow_manual_override: false,
            },
            resources: ResourceRequirements::default(),
        };
        let mut rewired = false;
        for edge in draft
            .edges
            .iter_mut()
            .filter(|edge| edge.to_node == commit.id)
        {
            edge.to_node.clone_from(&review_id);
            rewired = true;
        }
        if rewired {
            draft
                .edges
                .extend(ports.iter().map(|port| annotagent_core::WorkflowEdge {
                    from_node: review_id.clone(),
                    from_port: port.id.clone(),
                    to_node: commit.id.clone(),
                    to_port: port.id.clone(),
                    route: None,
                }));
        } else if let Some(commit_node) = draft.nodes.iter_mut().find(|node| node.id == commit.id) {
            commit_node.depends_on = vec![review_id.clone()];
        }
        draft.nodes.push(review);
    }
    if draft
        .nodes
        .iter()
        .all(|node| node.kind != WorkflowNodeKind::Commit)
    {
        bail!("geometry-safe migration requires at least one Commit node");
    }
    Ok(())
}

fn apply_localization_recovery_patch(
    draft: &mut WorkflowDraft,
    template: &annotagent_core::WorkflowTemplate,
    prompted_segmentation_model: Option<&str>,
) -> Result<bool> {
    let Some(image_id) = draft
        .nodes
        .iter()
        .find(|node| node.kind == WorkflowNodeKind::ImageInput)
        .map(|node| node.id.clone())
    else {
        return Ok(false);
    };
    let Some(detector_id) = draft
        .nodes
        .iter()
        .find(|node| {
            node.kind == WorkflowNodeKind::VisionLanguageModel
                && node
                    .outputs
                    .iter()
                    .any(|port| port.artifact_type == ArtifactKind::DetectionSet)
        })
        .map(|node| node.id.clone())
    else {
        return Ok(false);
    };
    let Some(review_id) = draft
        .nodes
        .iter()
        .find(|node| node.kind == WorkflowNodeKind::HumanReview)
        .map(|node| node.id.clone())
    else {
        return Ok(false);
    };
    let recovery_entry_id = draft
        .edges
        .iter()
        .find(|edge| edge.to_node == review_id)
        .map_or_else(|| detector_id.clone(), |edge| edge.from_node.clone());
    let Some(commit_id) = draft
        .nodes
        .iter()
        .find(|node| node.kind == WorkflowNodeKind::Commit)
        .map(|node| node.id.clone())
    else {
        return Ok(false);
    };
    if draft.nodes.iter().any(|node| {
        node.node_type == annotagent_runtime::CORE_EXPAND_REGION
            && node
                .parameters
                .get("localization_recovery_patch")
                .and_then(serde_json::Value::as_bool)
                == Some(true)
    }) {
        return Ok(false);
    }

    let detector = draft
        .nodes
        .iter()
        .find(|node| node.id == detector_id)
        .cloned()
        .ok_or_else(|| anyhow!("localization recovery detector disappeared"))?;
    let mut id_map = BTreeMap::from([
        ("image".to_owned(), image_id.clone()),
        ("coarse_localization".to_owned(), detector_id.clone()),
        ("select_coarse_ball".to_owned(), recovery_entry_id.clone()),
        ("review_final_ball".to_owned(), review_id.clone()),
        ("commit_final_ball".to_owned(), commit_id.clone()),
    ]);
    for node in &template.nodes {
        if id_map.contains_key(&node.id) {
            continue;
        }
        let base = format!("localization_recovery.{}", node.id);
        let mut id = base.clone();
        let mut suffix = 2_u32;
        while draft.nodes.iter().any(|existing| existing.id == id)
            || id_map.values().any(|mapped| mapped == &id)
        {
            id = format!("{base}.{suffix}");
            suffix = suffix.saturating_add(1);
        }
        id_map.insert(node.id.clone(), id);
    }

    let unavailable_refiner_nodes = BTreeSet::from([
        "refine_validated_prompt",
        "project_mask_bbox",
        "evaluate_refiner_geometry",
        "geometry_decision",
    ]);
    for source in &template.nodes {
        if matches!(
            source.id.as_str(),
            "image"
                | "coarse_localization"
                | "select_coarse_ball"
                | "review_final_ball"
                | "commit_final_ball"
        ) || prompted_segmentation_model.is_none()
            && unavailable_refiner_nodes.contains(source.id.as_str())
        {
            continue;
        }
        let mut node = source.clone();
        node.id.clone_from(&id_map[&source.id]);
        if node.kind == WorkflowNodeKind::VisionLanguageModel {
            node.model_binding.clone_from(&detector.model_binding);
            node.model_profile_binding
                .clone_from(&detector.model_profile_binding);
            node.unresolved_model_requirement
                .clone_from(&detector.unresolved_model_requirement);
        }
        if node.node_type == "capability.segment" {
            node.model_binding = prompted_segmentation_model.map(ToOwned::to_owned);
            node.model_profile_binding = None;
            node.unresolved_model_requirement = None;
        }
        if node.node_type == annotagent_runtime::CORE_EXPAND_REGION {
            node.parameters
                .insert("localization_recovery_patch".to_owned(), json!(true));
        }
        draft.nodes.push(node);
    }

    let coarse_template = template
        .nodes
        .iter()
        .find(|node| node.id == "coarse_localization")
        .ok_or_else(|| anyhow!("localization recovery template has no coarse detector"))?;
    if let Some(existing) = draft.nodes.iter_mut().find(|node| node.id == detector_id) {
        for key in [
            "labels",
            "prompt_resource_id",
            "prompt_resource_version",
            "prompt_resource_sha256",
            "target_description",
        ] {
            if let Some(value) = coarse_template.parameters.get(key) {
                existing.parameters.insert(key.to_owned(), value.clone());
            }
        }
    }

    draft.edges.retain(|edge| {
        edge.to_node != review_id && !(edge.to_node == commit_id && edge.from_node != review_id)
    });
    for source in &template.edges {
        if source.from_node == "coarse_localization" && source.to_node == "select_coarse_ball" {
            continue;
        }
        if prompted_segmentation_model.is_none()
            && (unavailable_refiner_nodes.contains(source.from_node.as_str())
                || unavailable_refiner_nodes.contains(source.to_node.as_str()))
        {
            continue;
        }
        let mut edge = source.clone();
        edge.from_node.clone_from(&id_map[&source.from_node]);
        edge.to_node.clone_from(&id_map[&source.to_node]);
        if !draft.edges.contains(&edge) {
            draft.edges.push(edge);
        }
    }
    if prompted_segmentation_model.is_none() {
        for gate in ["prompt_coverage_gate", "recovery_coverage_gate"] {
            let fallback = WorkflowEdge {
                from_node: id_map[gate].clone(),
                from_port: "detections".to_owned(),
                to_node: review_id.clone(),
                to_port: "detections".to_owned(),
                route: Some("refine".to_owned()),
            };
            if !draft.edges.contains(&fallback) {
                draft.edges.push(fallback);
            }
        }
    }
    draft
        .resource_versions
        .extend(template.resource_versions.clone());
    draft.label_pipeline = None;
    draft.updated_at = chrono::Utc::now();
    Ok(true)
}

fn compatibility_workflow(
    project: &ProjectSchema,
    skills: &[Arc<dyn DomainSkill>],
) -> WorkflowVersion {
    let graph_nodes = skills
        .iter()
        .flat_map(|skill| skill.workflow().nodes)
        .collect::<Vec<_>>();
    let dependency_map: HashMap<_, _> = graph_nodes
        .into_iter()
        .map(|node| (node.id, node.depends_on))
        .collect();
    let nodes = project
        .tasks
        .iter()
        .map(|task| WorkflowNodeSummary {
            id: task.id.to_string(),
            node_type: task_kind_name(task.kind),
            depends_on: dependency_map
                .get(&task.id)
                .unwrap_or(&task.depends_on)
                .iter()
                .map(ToString::to_string)
                .collect(),
            model_binding: Some("default-vision".to_owned()),
            validators: task.validators.clone(),
            refiners: task.refiners.clone(),
            human_review_gate: true,
            fallback: Some("bounded retry, then human review".to_owned()),
        })
        .collect();
    WorkflowVersion {
        workflow_id: format!(
            "{}-configured",
            if skills.is_empty() {
                "generic".to_owned()
            } else {
                skills
                    .iter()
                    .map(|skill| skill.id())
                    .collect::<Vec<_>>()
                    .join("+")
            }
        ),
        name: "Unpublished Project task graph".to_owned(),
        version: project.version.to_string(),
        status: WorkflowStatus::Draft,
        validation_status: "publish required".to_owned(),
        is_default: false,
        source: if skills.is_empty() {
            "Project Schema only".to_owned()
        } else {
            "Project Schema + registered Skill graphs only".to_owned()
        },
        nodes,
    }
}

fn published_workflow_summary(
    version: &PublishedWorkflowVersion,
    is_default: bool,
) -> WorkflowVersion {
    WorkflowVersion {
        workflow_id: version.workflow_id.clone(),
        name: version.draft.name.clone(),
        version: version.version.to_string(),
        status: WorkflowStatus::Published,
        validation_status: "valid".to_owned(),
        is_default,
        source: format!("published draft {}", version.source_draft_id),
        nodes: version
            .draft
            .nodes
            .iter()
            .map(|node| WorkflowNodeSummary {
                id: node.id.clone(),
                node_type: node.node_type.clone(),
                depends_on: node.depends_on.clone(),
                model_binding: node.model_binding.clone(),
                validators: node.validators.clone(),
                refiners: node.refiners.clone(),
                human_review_gate: node.review_gate || node.gate.required,
                fallback: node
                    .fallback_policy
                    .target_node
                    .clone()
                    .or_else(|| node.fallback.clone()),
            })
            .collect(),
    }
}

fn registry_requirement_for_node(
    node: &annotagent_core::WorkflowDraftNode,
) -> Option<(ModelCapability, ModelBindingRole)> {
    let requirement = match node.node_type.as_str() {
        annotagent_skill_classification::CLASSIFICATION_OPERATION | "capability.classify" => (
            ModelCapability::ImageClassification,
            ModelBindingRole::Classification,
        ),
        annotagent_skill_classification::CLASSIFICATION_VERIFY_OPERATION => (
            ModelCapability::ImageClassification,
            ModelBindingRole::Verification,
        ),
        annotagent_skill_open_vocabulary::OPEN_VOCABULARY_DETECTION_OPERATION => (
            ModelCapability::OpenVocabularyDetection,
            ModelBindingRole::Detection,
        ),
        annotagent_skill_open_vocabulary::PHRASE_GROUNDING_OPERATION => (
            ModelCapability::PhraseGrounding,
            ModelBindingRole::Detection,
        ),
        annotagent_skill_object_detection::OBJECT_DETECTION_OPERATION
        | annotagent_skill_yolo::YOLO_DETECTION_OPERATION
        | "capability.detect" => (
            ModelCapability::ObjectDetection,
            ModelBindingRole::Detection,
        ),
        annotagent_skill_vlm_detection::VLM_DETECTION_OPERATION | "vision_language" => (
            ModelCapability::VisionLanguage,
            ModelBindingRole::PrimaryInference,
        ),
        "capability.segment" | "prompted_segmentation" => (
            ModelCapability::PromptedSegmentation,
            ModelBindingRole::Segmentation,
        ),
        "capability.semantic_segment" | "semantic_segmentation" => (
            ModelCapability::SemanticSegmentation,
            ModelBindingRole::Segmentation,
        ),
        "instance_segmentation" => (
            ModelCapability::InstanceSegmentation,
            ModelBindingRole::Segmentation,
        ),
        _ if node.kind == WorkflowNodeKind::VisionLanguageModel => (
            ModelCapability::VisionLanguage,
            ModelBindingRole::PrimaryInference,
        ),
        _ if node.kind == WorkflowNodeKind::VisionModel
            && node
                .model_binding
                .as_deref()
                .is_some_and(|binding| binding.contains("classif")) =>
        {
            (
                ModelCapability::ImageClassification,
                ModelBindingRole::Classification,
            )
        }
        _ if node.kind == WorkflowNodeKind::VisionModel => (
            ModelCapability::ObjectDetection,
            ModelBindingRole::Detection,
        ),
        _ => return None,
    };
    Some(requirement)
}

#[cfg(test)]
fn workflow_catalog(settings: &Settings) -> Result<(NodeRegistry, ModelRegistry)> {
    workflow_catalog_with_api_key(settings, None)
}

fn workflow_catalog_with_api_key(
    settings: &Settings,
    temporary_api_key: Option<&str>,
) -> Result<(NodeRegistry, ModelRegistry)> {
    let capabilities = vec![
        VisionCapability::VisionLanguage,
        VisionCapability::OpenVocabularyDetection,
        VisionCapability::PhraseGrounding,
        VisionCapability::ObjectDetection,
        VisionCapability::SemanticSegmentation,
        VisionCapability::InstanceSegmentation,
        VisionCapability::PromptedSegmentation,
        VisionCapability::Classification,
        VisionCapability::KeypointDetection,
    ];
    let mut models = ModelRegistry::new();
    if settings.default_provider == "mock" {
        models.register_backend(Arc::new(MockVisionBackend::new(
            "workspace-provider-adapter",
            capabilities,
            Vec::new(),
        )))?;
    } else {
        let provider: Arc<dyn VisionModelProvider> = Arc::new(
            OpenAiCompatibleProvider::new_with_api_key(
                settings.provider.clone(),
                temporary_api_key.map(str::to_owned),
            )
            .map_err(|error| anyhow!(error))?,
        );
        models.register_backend(Arc::new(OpenAiVisionBackend::new(
            "workspace-provider-adapter",
            &settings.provider.model,
            provider,
            settings.provider.max_output_tokens,
            settings.provider.temperature,
        )))?;
    }
    models.register_model(VisionModelDescriptor {
        id: "default-vision".to_owned(),
        display_name: "Workspace default vision model".to_owned(),
        backend_id: "workspace-provider-adapter".to_owned(),
        capabilities: vec![
            VisionCapability::VisionLanguage,
            VisionCapability::Classification,
        ],
        input_types: vec![VisionInputType::Image, VisionInputType::Text],
        output_types: all_artifact_kinds().to_vec(),
        model: settings.provider.model.clone(),
        model_version: "provider-managed".to_owned(),
        endpoint_or_path: Some(settings.provider.endpoint.clone()),
        health: VisionModelHealth {
            status: if settings.default_provider == "mock" {
                VisionModelHealthStatus::Healthy
            } else {
                VisionModelHealthStatus::Unknown
            },
            detail: Some(if settings.default_provider == "mock" {
                "offline deterministic fixture available".to_owned()
            } else {
                "configured; health is verified on the next request".to_owned()
            }),
            checked_at: Some(chrono::Utc::now()),
        },
        limits: VisionModelLimits {
            max_images: Some(2),
            timeout_seconds: Some(settings.provider.request_timeout_seconds),
            ..VisionModelLimits::default()
        },
        secret_reference: (settings.default_provider != "mock")
            .then(|| format!("env:{}", settings.provider.api_key_env)),
        configuration: BTreeMap::from([
            ("provider".to_owned(), json!(settings.default_provider)),
            ("model".to_owned(), json!(settings.provider.model)),
        ]),
        ..VisionModelDescriptor::default()
    })?;
    if settings.default_provider == "mock" {
        models.register_model(VisionModelDescriptor {
            id: "mock-open-vocabulary".to_owned(),
            display_name: "Offline mock open-vocabulary grounding".to_owned(),
            backend_id: "workspace-provider-adapter".to_owned(),
            capabilities: vec![
                VisionCapability::OpenVocabularyDetection,
                VisionCapability::PhraseGrounding,
            ],
            input_types: vec![VisionInputType::Image, VisionInputType::Text],
            output_types: vec![ArtifactKind::DetectionSet],
            model: "mock-open-vocabulary".to_owned(),
            model_version: "1".to_owned(),
            input_contract: ModelInputContract {
                input_types: vec![VisionInputType::Image, VisionInputType::Text],
                supports_multiple_queries: true,
                supports_visual_prompt: false,
                max_queries: Some(100),
            },
            output_contract: ModelOutputContract {
                output_types: vec![ArtifactKind::DetectionSet],
                normalized_coordinates: true,
                allows_empty: true,
                label_space: Vec::new(),
            },
            score_semantics: ScoreSemantics::NotProvided,
            health: VisionModelHealth {
                status: VisionModelHealthStatus::Healthy,
                detail: Some("offline deterministic Grounding fixture available".to_owned()),
                checked_at: Some(chrono::Utc::now()),
            },
            ..VisionModelDescriptor::default()
        })?;
    }
    for worker in &settings.detection_workers {
        let authorization = worker.authorization_header().ok().flatten();
        models.register_backend(Arc::new(HttpJsonVisionBackend::new(
            HttpJsonVisionBackendConfig {
                id: worker.id.clone(),
                endpoint: format!("{}/v1/infer", worker.base_url.trim_end_matches('/')),
                capabilities: worker.expected_capabilities.clone(),
                request_timeout: Duration::from_secs(worker.timeout_seconds),
                authorization,
                expected_model_identity: Some(worker.model_id.clone()),
                max_retries: worker.max_retries,
                max_response_bytes: worker.max_response_bytes,
                allow_remote: worker.allow_remote,
            },
        )?))?;
        models.register_expert_manifest(worker.expert_manifest()?)?;
    }
    if settings.default_provider == "mock" {
        for (id, display_name, capability, output_type) in [
            (
                "mock-classifier",
                "Offline mock classifier",
                VisionCapability::Classification,
                ArtifactKind::ClassificationSet,
            ),
            (
                "mock-detector",
                "Offline mock detector",
                VisionCapability::ObjectDetection,
                ArtifactKind::DetectionSet,
            ),
            (
                "mock-object-detector",
                "Offline mock trained detector",
                VisionCapability::ObjectDetection,
                ArtifactKind::DetectionSet,
            ),
            (
                "mock-prompted-segmenter",
                "Offline mock prompted segmenter",
                VisionCapability::PromptedSegmentation,
                ArtifactKind::MaskSet,
            ),
        ] {
            models.register_model(VisionModelDescriptor {
                id: id.to_owned(),
                display_name: display_name.to_owned(),
                backend_id: "workspace-provider-adapter".to_owned(),
                capabilities: vec![capability],
                input_types: vec![VisionInputType::Image],
                output_types: vec![output_type],
                model: id.to_owned(),
                model_version: "1".to_owned(),
                health: VisionModelHealth {
                    status: VisionModelHealthStatus::Healthy,
                    detail: Some("offline deterministic fixture available".to_owned()),
                    checked_at: Some(chrono::Utc::now()),
                },
                ..VisionModelDescriptor::default()
            })?;
        }
    }

    let mut nodes = NodeRegistry::new();
    let artifact_kinds = all_artifact_kinds().to_vec();
    for (id, capability, produces, deterministic) in [
        (
            "vision_language",
            Some(VisionCapability::VisionLanguage),
            artifact_kinds.clone(),
            false,
        ),
        (
            "object_detection",
            Some(VisionCapability::ObjectDetection),
            vec![ArtifactKind::BoundingBox],
            false,
        ),
        (
            "semantic_segmentation",
            Some(VisionCapability::SemanticSegmentation),
            vec![ArtifactKind::SemanticMask],
            false,
        ),
        (
            "instance_segmentation",
            Some(VisionCapability::InstanceSegmentation),
            vec![ArtifactKind::InstanceMask],
            false,
        ),
        (
            "prompted_segmentation",
            Some(VisionCapability::PromptedSegmentation),
            vec![ArtifactKind::MaskSet],
            false,
        ),
        (
            "classification",
            Some(VisionCapability::Classification),
            vec![ArtifactKind::Classification],
            false,
        ),
        (
            "keypoint_detection",
            Some(VisionCapability::KeypointDetection),
            vec![ArtifactKind::Keypoints],
            false,
        ),
        (
            "deterministic_cv",
            None,
            vec![ArtifactKind::Polygon, ArtifactKind::Polyline],
            true,
        ),
        (
            "field_line_refiner",
            None,
            vec![ArtifactKind::Polyline],
            true,
        ),
        (
            "annotation_refiner",
            None,
            vec![ArtifactKind::DetectionSet],
            false,
        ),
        ("static_validator", None, artifact_kinds.clone(), true),
        ("review_gate", None, artifact_kinds.clone(), true),
        ("commit", None, artifact_kinds, true),
    ] {
        nodes.register(VisionNodeDescriptor {
            id: id.to_owned(),
            display_name: id.replace('_', " "),
            required_capabilities: capability.into_iter().collect(),
            accepts: all_artifact_kinds().to_vec(),
            produces,
            deterministic,
        })?;
    }
    for descriptor in [
        annotagent_skill_classification::node_descriptor(),
        annotagent_skill_classification::verifier_node_descriptor(),
        annotagent_skill_open_vocabulary::open_vocabulary_node_descriptor(),
        annotagent_skill_open_vocabulary::phrase_grounding_node_descriptor(),
        annotagent_skill_object_detection::node_descriptor(),
        annotagent_skill_vlm_detection::node_descriptor(),
        annotagent_skill_yolo::node_descriptor(),
        VisionNodeDescriptor {
            id: annotagent_core::IMAGE_INPUT_OPERATION.to_owned(),
            display_name: "Image Input".to_owned(),
            required_capabilities: Vec::new(),
            accepts: Vec::new(),
            produces: vec![ArtifactKind::Image],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_ARTIFACT_CACHE.to_owned(),
            display_name: "Artifact Cache".to_owned(),
            required_capabilities: Vec::new(),
            accepts: all_artifact_kinds().to_vec(),
            produces: all_artifact_kinds().to_vec(),
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_IMAGE_STATISTICS.to_owned(),
            display_name: "Compute Image Statistics".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::Image],
            produces: vec![ArtifactKind::Attributes],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_CROP.to_owned(),
            display_name: "Crop".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::Image, ArtifactKind::DetectionSet],
            produces: vec![ArtifactKind::CropSet, ArtifactKind::Image],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_FILTER.to_owned(),
            display_name: "Select detections".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::DetectionSet],
            produces: vec![ArtifactKind::DetectionSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_MAP_LABEL.to_owned(),
            display_name: "Select detections · label mapping".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::DetectionSet],
            produces: vec![ArtifactKind::DetectionSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_ATTACH_RESULT.to_owned(),
            display_name: "Combine model evidence".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::DetectionSet, ArtifactKind::ClassificationSet],
            produces: vec![ArtifactKind::AnnotationCandidateSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_ATTACH_ATTRIBUTE.to_owned(),
            display_name: "Attach Attribute".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::AnnotationCandidateSet],
            produces: vec![ArtifactKind::AnnotationCandidateSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_CONFIDENCE_GATE.to_owned(),
            display_name: "Decision".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![
                ArtifactKind::DetectionSet,
                ArtifactKind::ClassificationSet,
                ArtifactKind::AnnotationCandidateSet,
            ],
            produces: vec![
                ArtifactKind::DetectionSet,
                ArtifactKind::ClassificationSet,
                ArtifactKind::AnnotationCandidateSet,
            ],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_CANDIDATE_MATCH.to_owned(),
            display_name: "Combine model evidence".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::DetectionSet],
            produces: vec![ArtifactKind::CandidateClusterSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_EVIDENCE_GATE.to_owned(),
            display_name: "Decision · evidence".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::CandidateClusterSet],
            produces: vec![ArtifactKind::CandidateClusterSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_PROJECT_CANDIDATES.to_owned(),
            display_name: "Select detections".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![ArtifactKind::CandidateClusterSet],
            produces: vec![ArtifactKind::DetectionSet],
            deterministic: true,
        },
        VisionNodeDescriptor {
            id: annotagent_runtime::CORE_REJECT.to_owned(),
            display_name: "Reject Candidates".to_owned(),
            required_capabilities: Vec::new(),
            accepts: vec![
                ArtifactKind::DetectionSet,
                ArtifactKind::CandidateClusterSet,
                ArtifactKind::ClassificationSet,
                ArtifactKind::AnnotationCandidateSet,
            ],
            produces: vec![
                ArtifactKind::DetectionSet,
                ArtifactKind::CandidateClusterSet,
                ArtifactKind::ClassificationSet,
                ArtifactKind::AnnotationCandidateSet,
            ],
            deterministic: true,
        },
        annotagent_runtime::detection_recovery_node_descriptor(),
    ] {
        nodes.register(descriptor)?;
    }
    register_public_annotation_catalog(&mut nodes)?;
    Ok((nodes, models))
}

fn normalize_profile_compatibility_bindings(
    draft: &mut WorkflowDraft,
    models: &ModelRegistry,
) -> Result<()> {
    let available = models.models();
    for node in &mut draft.nodes {
        if node.model_profile_binding.is_none() {
            continue;
        }
        let Some((capability, _)) = registry_requirement_for_node(node) else {
            continue;
        };
        let runtime_capability = match capability {
            ModelCapability::TextGeneration | ModelCapability::VisionLanguage => {
                VisionCapability::VisionLanguage
            }
            ModelCapability::ImageClassification => VisionCapability::Classification,
            ModelCapability::ObjectDetection => VisionCapability::ObjectDetection,
            ModelCapability::OpenVocabularyDetection => VisionCapability::OpenVocabularyDetection,
            ModelCapability::PhraseGrounding => VisionCapability::PhraseGrounding,
            ModelCapability::SemanticSegmentation => VisionCapability::SemanticSegmentation,
            ModelCapability::PromptedSegmentation => VisionCapability::PromptedSegmentation,
            ModelCapability::InstanceSegmentation => VisionCapability::InstanceSegmentation,
            ModelCapability::KeypointDetection => VisionCapability::KeypointDetection,
        };
        let compatibility_model = available
            .iter()
            .find(|model| Some(model.id.as_str()) == node.model_binding.as_deref())
            .or_else(|| available.iter().find(|model| model.capabilities.contains(&runtime_capability)))
            .ok_or_else(|| {
                anyhow!(
                    "no Runtime compatibility model is registered for Profile-bound node {:?} with capability {:?}",
                    node.id,
                    capability
                )
        })?;
        node.model_binding = Some(compatibility_model.id.clone());
        // The authored composition and compiled node must reference the same adapter.
        // Registry Model Profile identity remains on the node and frozen snapshot.
        if let Some(composition) = &mut draft.label_pipeline {
            for step in composition
                .shared_stages
                .iter_mut()
                .flat_map(|stage| &mut stage.steps)
                .chain(
                    composition
                        .label_pipelines
                        .iter_mut()
                        .flat_map(|pipeline| &mut pipeline.steps),
                )
            {
                if step.id == node.id {
                    let binding = step
                        .model_binding
                        .get_or_insert_with(|| PipelineModelBinding {
                            model_id: compatibility_model.id.clone(),
                            capability: runtime_capability,
                            configuration: BTreeMap::new(),
                        });
                    binding.model_id.clone_from(&compatibility_model.id);
                    binding.capability = runtime_capability;
                }
            }
        }
    }
    Ok(())
}

fn plugin_model_selection(value: &str) -> bool {
    value.starts_with("plugin:") || parse_model_instance_selection_id(value).is_some()
}

fn workflow_requires_original_model_image(draft: &WorkflowDraft) -> bool {
    draft.nodes.iter().any(|node| {
        node.model_binding
            .as_deref()
            .is_some_and(plugin_model_selection)
    })
}

fn workflow_model_image_max_dimension(draft: &WorkflowDraft, width: u32, height: u32) -> u32 {
    if workflow_requires_original_model_image(draft) {
        width.max(height)
    } else {
        1280
    }
}

fn catalog_port(
    name: &str,
    artifact_type: ArtifactKind,
    required: bool,
    cardinality: PortCardinality,
) -> PortDefinition {
    PortDefinition {
        name: name.to_owned(),
        artifact_type,
        required,
        cardinality,
    }
}

fn node_schema(properties: impl Into<serde_json::Value>) -> serde_json::Value {
    let properties = properties.into();
    json!({
        "type": "object",
        "additionalProperties": false,
        "properties": properties,
    })
}

