/// Release a scoped execution lease even during cancellation or unwinding.
struct ReleaseOnDrop<F: FnOnce()>(Option<F>);
impl<F: FnOnce()> Drop for ReleaseOnDrop<F> {
    fn drop(&mut self) {
        if let Some(release) = self.0.take() {
            release();
        }
    }
}

/// Lifecycle of one existing sandbox invocation, not a separate execution engine.
pub struct SampleExecutionControl {
    pub id: String,
    pub cancellation: CancellationToken,
    pub check_scope: Option<Arc<dyn Fn() -> Result<()> + Send + Sync>>,
    /// Server-owned accounting context, never deserialized from a browser request.
    pub conversation_calls: Option<ConversationVisionCalls>,
}

impl Default for SampleExecutionControl {
    fn default() -> Self {
        Self {
            id: uuid::Uuid::new_v4().to_string(),
            cancellation: CancellationToken::new(),
            check_scope: None,
            conversation_calls: None,
        }
    }
}

struct SamplePlanRevisionLease<'a> {
    application: &'a LocalApplication,
    scope: annotagent_storage::ManagementScope,
    object: annotagent_core::ManagementObjectRef,
    owner: String,
}

impl Drop for SamplePlanRevisionLease<'_> {
    fn drop(&mut self) {
        let _ = self.application.store.release_management_lease(
            &self.scope,
            &self.object,
            "sample_plan_revision",
            &self.owner,
        );
    }
}

/// Persist a terminal state even when an advisor future returns early or is dropped.
struct AgentExecutionGuard<'a> {
    application: &'a LocalApplication,
    session_id: uuid::Uuid,
}

impl Drop for AgentExecutionGuard<'_> {
    fn drop(&mut self) {
        if let Ok(mut session) = self.application.store.get_agent_session(self.session_id)
            && session.status == AgentSessionStatus::Running
        {
            session.fail("Pipeline Builder execution ended before producing a final result (request interrupted or internal error). The saved Draft and execution evidence were preserved.");
            session.next_action =
                Some("Inspect the saved steps and retry from the preserved Draft".to_owned());
            if let Err(error) = self.application.store.save_agent_session(&session) {
                eprintln!(
                    "could not finalize interrupted Agent session {}: {error}",
                    self.session_id
                );
            }
        }
        if let Ok(mut cancellations) = self.application.agent_cancellations.lock() {
            cancellations.remove(&self.session_id);
        }
    }
}

