    pub fn project_geometry_policies(
        &self,
        project_id: &str,
    ) -> Result<Vec<ProjectGeometryPolicy>> {
        let project_path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&project_path, &self.skills)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let stored = self.store.list_project_geometry_policies(stable_id)?;
        let mut policies = Vec::new();
        for task_kind in project
            .tasks
            .iter()
            .map(|task| task.kind)
            .collect::<BTreeSet<_>>()
        {
            policies.push(
                stored
                    .iter()
                    .find(|policy| policy.task_kind == task_kind)
                    .cloned()
                    .unwrap_or_else(|| {
                        ProjectGeometryPolicy::conservative_default(stable_id, task_kind)
                    }),
            );
        }
        Ok(policies)
    }

    pub fn save_project_geometry_policy(
        &self,
        project_id: &str,
        mut policy: ProjectGeometryPolicy,
    ) -> Result<ProjectGeometryPolicy> {
        let project_path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&project_path, &self.skills)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        if !project
            .tasks
            .iter()
            .any(|task| task.kind == policy.task_kind)
        {
            bail!(
                "Project has no {:?} task for this geometry policy",
                policy.task_kind
            );
        }
        policy.project_id = stable_id;
        policy.validate().map_err(|error| anyhow!(error))?;
        self.store.save_project_geometry_policy(&policy)?;
        Ok(policy)
    }

    pub fn create_geometry_calibration(
        &self,
        project_id: &str,
        request: &GeometryCalibrationRequest,
    ) -> Result<GeometryCalibrationReport> {
        if request.evidence_run_ids.is_empty() {
            bail!("geometry calibration requires at least one explicitly selected Evidence Run");
        }
        let project_path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&project_path, &self.skills)?;
        let published = self
            .store
            .get_published_workflow_version(&request.workflow_id, request.workflow_version)?;
        if published.project_id != project_id {
            bail!("calibration Workflow does not belong to the requested Project");
        }
        let task = project
            .tasks
            .iter()
            .find(|task| task.id == request.task_id)
            .ok_or_else(|| anyhow!("calibration task does not exist in the Project"))?;
        if task.kind != TaskKind::BoundingBox {
            bail!("geometry calibration currently requires a bounding-box task");
        }
        if request.label_id.as_ref().is_some_and(|label| {
            !task
                .labels
                .iter()
                .any(|candidate| candidate == label.as_str())
        }) {
            bail!("calibration Label does not exist in the selected task");
        }
        let key = self.geometry_calibration_key(
            project_id,
            &project,
            &published.draft,
            &published.snapshot.model_profiles,
            &request.node_id,
            (request.task_id.clone(), request.label_id.clone()),
        )?;
        let selected_runs = request
            .evidence_run_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        let persisted_runs = self.store.list_runs()?;
        for run_id in &selected_runs {
            let run = persisted_runs
                .iter()
                .find(|run| run.id == *run_id)
                .ok_or_else(|| anyhow!("Evidence Run {run_id} does not exist"))?;
            if run.project_id != Some(key.project_id) {
                bail!("Evidence Run {run_id} does not belong to the requested Project");
            }
            let evidence_workflow = run
                .workflow_snapshot_json
                .as_deref()
                .and_then(|snapshot| serde_json::from_str::<serde_json::Value>(snapshot).ok())
                .and_then(|snapshot| snapshot.get("selected_workflow").cloned())
                .and_then(|workflow| {
                    serde_json::from_value::<PublishedWorkflowVersion>(workflow).ok()
                })
                .ok_or_else(|| {
                    anyhow!(
                        "Evidence Run {run_id} has no exact immutable Published Workflow snapshot"
                    )
                })?;
            if evidence_workflow.workflow_id != published.workflow_id
                || evidence_workflow.version != published.version
                || evidence_workflow.content_hash != published.content_hash
            {
                bail!("Evidence Run {run_id} does not use the selected immutable Workflow Version");
            }
        }
        let mut all_evidence = Vec::new();
        for run_id in &selected_runs {
            all_evidence.extend(self.store.list_run_geometry_corrections(*run_id, 1_000)?);
        }
        let mut scoped_evidence = Vec::new();
        let mut seen_samples = BTreeSet::new();
        for (report, evidence) in all_evidence {
            if !selected_runs.contains(&evidence.run_id)
                || evidence.source_node_id.as_str() != request.node_id
                || evidence.source_model_profile_id != Some(key.model_profile_id)
                || evidence.source_model_revision != Some(key.model_profile_revision)
                || report
                    .issue_codes
                    .contains(&annotagent_core::GeometryIssueCode::InsufficientEvidence)
                || !matches!(
                    &evidence.reason,
                    GeometryCorrectionReason::TooLoose
                        | GeometryCorrectionReason::TooTight
                        | GeometryCorrectionReason::Shifted
                        | GeometryCorrectionReason::Other
                )
            {
                continue;
            }
            let annotation_matches = self
                .store
                .find_annotation(evidence.annotation_id)?
                .is_some_and(|(run_id, annotation)| {
                    run_id == evidence.run_id
                        && annotation.task_id == request.task_id
                        && request
                            .label_id
                            .as_ref()
                            .is_none_or(|label| annotation.label.as_ref() == Some(label))
                });
            if annotation_matches && seen_samples.insert((evidence.run_id, evidence.annotation_id))
            {
                scoped_evidence.push((report, evidence));
            }
        }
        let evaluated_sample_count = selected_runs
            .iter()
            .map(|run_id| {
                self.store.list_annotations(*run_id).map(|annotations| {
                    annotations
                        .into_iter()
                        .filter(|annotation| {
                            annotation.task_id == request.task_id
                                && request
                                    .label_id
                                    .as_ref()
                                    .is_none_or(|label| annotation.label.as_ref() == Some(label))
                                && matches!(
                                    annotation.review_status,
                                    ReviewStatus::HumanAccepted | ReviewStatus::Rejected
                                )
                        })
                        .count()
                })
            })
            .collect::<std::result::Result<Vec<_>, _>>()?
            .into_iter()
            .sum::<usize>()
            .try_into()
            .unwrap_or(u32::MAX);
        let thresholds = self
            .project_geometry_policies(project_id)?
            .into_iter()
            .find(|policy| policy.task_kind == task.kind)
            .map_or_else(Default::default, |policy| policy.calibration_thresholds);
        let report = annotagent_core::evaluate_geometry_calibration(
            key,
            thresholds,
            &scoped_evidence,
            evaluated_sample_count,
            chrono::Utc::now(),
        );
        self.store.save_geometry_calibration(&report)?;
        Ok(report)
    }

    pub fn project_geometry_calibrations(
        &self,
        project_id: &str,
    ) -> Result<Vec<GeometryCalibrationView>> {
        let project_path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&project_path, &self.skills)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let reports = self.store.list_project_geometry_calibrations(stable_id)?;
        let current = self
            .store
            .list_published_workflow_versions(Some(project_id))?
            .into_iter()
            .last();
        reports
            .into_iter()
            .map(|report| {
                let current_keys = current.as_ref().map_or_else(Vec::new, |workflow| {
                    workflow
                        .draft
                        .nodes
                        .iter()
                        .filter(|node| node.node_type == report.key.node_definition_id)
                        .filter_map(|node| {
                            self.geometry_calibration_key(
                                project_id,
                                &project,
                                &workflow.draft,
                                &workflow.snapshot.model_profiles,
                                &node.id,
                                (report.key.task_id.clone(), report.key.label_id.clone()),
                            )
                            .ok()
                        })
                        .collect::<Vec<_>>()
                });
                let current_key = current_keys
                    .iter()
                    .find(|key| report.exact_key_match(key))
                    .or_else(|| {
                        current_keys
                            .iter()
                            .find(|key| calibration_scope_related(&report.key, key))
                    })
                    .or_else(|| current_keys.first());
                let (effective_status, staleness_reasons) = match current_key {
                    Some(key) => (report.effective_status(key), report.staleness_reasons(key)),
                    _ => (
                        GeometryCalibrationStatus::Stale,
                        vec![GeometryCalibrationStaleness::NodeDefinition],
                    ),
                };
                Ok(GeometryCalibrationView {
                    report,
                    effective_status,
                    staleness_reasons,
                })
            })
            .collect()
    }

    pub fn geometry_calibration(
        &self,
        id: annotagent_core::GeometryCalibrationId,
    ) -> Result<Option<GeometryCalibrationReport>> {
        self.store
            .get_geometry_calibration(id)
            .map_err(anyhow::Error::from)
    }

    pub fn create_pipeline_improvement(
        &self,
        project_id: &str,
        settings: &Settings,
        request: &CreatePipelineImprovementRequest,
    ) -> Result<PipelineImprovementSession> {
        if request.evidence_run_ids.is_empty() {
            bail!("Pipeline improvement requires at least one selected Evidence Run");
        }
        if request.evidence_run_ids.len() > 100 || request.evaluation_run_ids.len() > 100 {
            bail!("Pipeline improvement accepts at most 100 diagnosis and 100 evaluation Runs");
        }
        if request
            .evidence_run_ids
            .iter()
            .copied()
            .collect::<BTreeSet<_>>()
            .len()
            != request.evidence_run_ids.len()
            || request
                .evaluation_run_ids
                .iter()
                .copied()
                .collect::<BTreeSet<_>>()
                .len()
                != request.evaluation_run_ids.len()
        {
            bail!("Pipeline improvement Run selections must not contain duplicates");
        }
        if request
            .evidence_run_ids
            .iter()
            .any(|run_id| request.evaluation_run_ids.contains(run_id))
        {
            bail!("diagnosis Evidence Runs and evaluation holdout Runs must be disjoint");
        }
        let project_path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&project_path, &self.skills)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let task = project
            .tasks
            .iter()
            .find(|task| task.id == request.target_task_id)
            .ok_or_else(|| anyhow!("Pipeline improvement target task does not exist"))?;
        if task.kind != TaskKind::BoundingBox {
            bail!("geometry-safe Pipeline improvement currently requires a bounding-box task");
        }
        if !task
            .labels
            .iter()
            .any(|label| label == request.target_label.as_str())
        {
            bail!("Pipeline improvement target Label does not exist");
        }
        let published = self
            .store
            .get_published_workflow_version(&request.workflow_id, request.workflow_version)?;
        if published.project_id != project_id {
            bail!("baseline Workflow does not belong to the requested Project");
        }

        let mut failure_counts = BTreeMap::<AnnotationFailureClass, u32>::new();
        let mut localization_failure_classes = BTreeSet::<LocalizationFailureClass>::new();
        let mut geometry_correction_count = 0_u32;
        let mut semantic_target_correct_count = 0_u32;
        let mut correction_reason_counts = BTreeMap::<GeometryCorrectionReason, u32>::new();
        for run_id in request
            .evidence_run_ids
            .iter()
            .chain(request.evaluation_run_ids.iter())
        {
            let history = self.store.history(*run_id)?;
            if history.run.project_id != Some(stable_id) {
                bail!("Run {run_id} does not belong to the requested Project");
            }
            if request.evidence_run_ids.contains(run_id) {
                for event in &history.events {
                    let class = match &event.payload {
                        RunEventPayload::ProviderFailure { .. } => {
                            Some(AnnotationFailureClass::ProviderFailure)
                        }
                        RunEventPayload::TaskFailure {
                            error_code,
                            summary,
                            ..
                        } => {
                            localization_failure_classes.extend(
                                annotagent_core::classify_localization_failures(
                                    error_code, summary,
                                ),
                            );
                            Some(annotagent_core::classify_annotation_failure(
                                error_code, summary,
                            ))
                        }
                        RunEventPayload::Validation {
                            issue_codes,
                            accepted,
                        } if !accepted || !issue_codes.is_empty() => {
                            if let Some(code) = issue_codes.first() {
                                localization_failure_classes.extend(
                                    annotagent_core::classify_localization_failures(code, code),
                                );
                            }
                            issue_codes.first().map(|code| {
                                annotagent_core::classify_annotation_failure(code, code)
                            })
                        }
                        _ => None,
                    };
                    if let Some(class) = class {
                        *failure_counts.entry(class).or_default() += 1;
                    }
                }
                if let Some(reason) = history.run.terminal_reason.as_deref() {
                    localization_failure_classes.extend(
                        annotagent_core::classify_localization_failures("terminal", reason),
                    );
                    let class = annotagent_core::classify_annotation_failure("terminal", reason);
                    *failure_counts.entry(class).or_default() += 1;
                }
                for (_, evidence) in self.store.list_run_geometry_corrections(*run_id, 1_000)? {
                    let Some((_, annotation)) =
                        self.store.find_annotation(evidence.annotation_id)?
                    else {
                        continue;
                    };
                    if annotation.task_id != request.target_task_id
                        || annotation.label.as_ref() != Some(&request.target_label)
                    {
                        continue;
                    }
                    *correction_reason_counts
                        .entry(evidence.reason.clone())
                        .or_default() += 1;
                    let class = match &evidence.reason {
                        GeometryCorrectionReason::TooLoose
                        | GeometryCorrectionReason::TooTight
                        | GeometryCorrectionReason::Shifted
                        | GeometryCorrectionReason::Other => {
                            geometry_correction_count = geometry_correction_count.saturating_add(1);
                            semantic_target_correct_count =
                                semantic_target_correct_count.saturating_add(1);
                            AnnotationFailureClass::GeometryError
                        }
                        GeometryCorrectionReason::MissedObject => {
                            localization_failure_classes
                                .insert(LocalizationFailureClass::CoarseLocalizationMiss);
                            AnnotationFailureClass::NoCandidate
                        }
                        GeometryCorrectionReason::DomainRisk(_) => {
                            AnnotationFailureClass::DomainRisk
                        }
                        GeometryCorrectionReason::WrongObject
                        | GeometryCorrectionReason::Duplicate
                        | GeometryCorrectionReason::WrongLabel => {
                            AnnotationFailureClass::SemanticError
                        }
                    };
                    *failure_counts.entry(class).or_default() += 1;
                }
            }
        }
        let primary_failure_class = failure_counts
            .iter()
            .max_by_key(|(class, count)| (**count, failure_priority(**class)))
            .map_or(
                AnnotationFailureClass::InsufficientEvidence,
                |(class, _)| *class,
            );
        let provider_failure_count = failure_counts
            .get(&AnnotationFailureClass::ProviderFailure)
            .copied()
            .unwrap_or_default();
        let no_candidate_count = failure_counts
            .get(&AnnotationFailureClass::NoCandidate)
            .copied()
            .unwrap_or_default();
        let mut evidence_statements = failure_counts
            .iter()
            .map(|(class, count)| format!("Observed {count} structured {class:?} signal(s)."))
            .collect::<Vec<_>>();
        evidence_statements.extend(
            correction_reason_counts
                .iter()
                .map(|(reason, count)| format!("Observed {count} human {reason:?} correction(s).")),
        );
        if evidence_statements.is_empty() {
            evidence_statements.push(
                "The selected Evidence Runs contain no scoped correction or failure signal."
                    .to_owned(),
            );
        }

        let baseline = self.clone_workflow_version(&published.workflow_id, published.version)?;
        let now = chrono::Utc::now();
        let mut candidate = baseline.clone();
        candidate.id = uuid::Uuid::new_v4().to_string();
        candidate.name = format!("{} (evidence repair)", baseline.name);
        candidate.status = WorkflowDraftStatus::Editing;
        candidate.geometry_risk_acceptance = None;
        candidate.created_at = now;
        candidate.updated_at = now;
        let mut suggestion = WorkflowSuggestion {
            draft: candidate,
            rationale: vec![format!(
                "Patch is scoped to {} / {} from explicitly selected Review evidence.",
                request.target_task_id, request.target_label
            )],
            estimated_model_calls_per_image: 0,
            estimated_latency_ms: None,
            estimated_cost_tier: "must be measured by before/after Dry Run".to_owned(),
            unresolved_model_bindings: Vec::new(),
            warnings: Vec::new(),
            alternatives: Vec::new(),
        };
        let mut setup_requirements = Vec::new();
        let needs_localization_recovery = localization_failure_classes.iter().any(|class| {
            matches!(
                class,
                LocalizationFailureClass::CoarseLocalizationMiss
                    | LocalizationFailureClass::PromptCoverageFailure
                    | LocalizationFailureClass::RefinerDrift
            )
        });
        if needs_localization_recovery {
            let templates = workflow_templates_for(
                &self.skills,
                &project
                    .project
                    .enabled_skill_versions()
                    .into_keys()
                    .collect::<Vec<_>>(),
            )?;
            let template = templates
                .iter()
                .find(|template| {
                    template
                        .nodes
                        .iter()
                        .any(|node| node.node_type == annotagent_runtime::CORE_EXPAND_REGION)
                        && template.nodes.iter().any(|node| {
                            node.node_type == annotagent_runtime::CORE_PROMPT_COVERAGE_GATE
                        })
                })
                .ok_or_else(|| {
                    anyhow!("enabled Skills do not provide a typed localization-recovery template")
                })?;
            let (_, models) = self.workflow_catalog(settings)?;
            let segmenter = available_model_for_capability(
                &models.models(),
                VisionCapability::PromptedSegmentation,
            )
            .ok();
            if !apply_localization_recovery_patch(
                &mut suggestion.draft,
                template,
                segmenter.as_deref(),
            )? {
                setup_requirements.push(
                    "The existing Draft could not be incrementally patched; preserve it and create a reviewed recovery Draft manually."
                        .to_owned(),
                );
            }
            if segmenter.is_none() {
                setup_requirements.push(
                    "Prompted segmentation is retained as a Setup Alternative; until a production-eligible model is Ready, recovered candidates route to mandatory Human Review."
                        .to_owned(),
                );
            }
            suggestion.rationale.push(format!(
                "Added a local recovery subgraph for structured localization evidence: {}.",
                localization_failure_classes
                    .iter()
                    .map(|class| format!("{class:?}"))
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        } else if primary_failure_class == AnnotationFailureClass::GeometryError {
            let (_, models) = self.workflow_catalog(settings)?;
            let model_descriptors = models.models();
            let mut summary = AgentDryRunSummary {
                geometry_review_count: geometry_correction_count,
                ..AgentDryRunSummary::default()
            };
            summary.geometry_quality.geometry_review_count = geometry_correction_count;
            summary.geometry_quality.human_adjustment_count = geometry_correction_count;
            summary.geometry_quality.inaccurate_bbox_reason_count = geometry_correction_count;
            let applied = available_model_for_capability(
                &model_descriptors,
                VisionCapability::PromptedSegmentation,
            )
            .ok()
            .and_then(|model_id| {
                match add_prompted_segmentation_revision(
                    &mut suggestion,
                    request.target_task_id.as_str(),
                    request.target_label.as_str(),
                    &model_id,
                    &summary,
                ) {
                    Ok(true) => Some(true),
                    Ok(false) => None,
                    Err(error) => {
                        setup_requirements.push(format!(
                            "Prompted geometry repair could not patch this Pipeline: {error}"
                        ));
                        None
                    }
                }
            })
            .unwrap_or(false);
            if !applied {
                setup_requirements.push(
                    "Configure an Available prompted-segmentation Model Profile and a typed DetectionSet → BoxPromptSet → MaskSet → DetectionSet path."
                        .to_owned(),
                );
                add_mandatory_geometry_review_boundaries(&mut suggestion.draft)?;
                suggestion.draft.label_pipeline = None;
            }
        } else {
            add_mandatory_geometry_review_boundaries(&mut suggestion.draft)?;
            suggestion.draft.label_pipeline = None;
            setup_requirements.push(match primary_failure_class {
                AnnotationFailureClass::ProviderFailure
                | AnnotationFailureClass::InfrastructureFailure =>
                    "Repair Provider or worker availability before changing geometry nodes.".to_owned(),
                AnnotationFailureClass::NoCandidate =>
                    "Evaluate detector recall or fallback candidates; prompted segmentation cannot refine an absent box.".to_owned(),
                AnnotationFailureClass::SemanticError | AnnotationFailureClass::DomainRisk =>
                    "Add semantic verification or hard-negative handling before considering geometry refinement.".to_owned(),
                _ =>
                    "Collect scoped human correction evidence before recommending a model-chain change.".to_owned(),
            });
        }
        let candidate = self.save_workflow_draft(suggestion.draft)?;
        let validation = self.validate_workflow_draft(&candidate, settings, false)?;
        let diff = PipelineDraftDiff::between(&baseline, &candidate).map_err(anyhow::Error::msg)?;
        let session = PipelineImprovementSession {
            schema_version: PIPELINE_IMPROVEMENT_SCHEMA_VERSION,
            id: PipelineImprovementId::new(),
            project_id: project_id.to_owned(),
            baseline_workflow_id: published.workflow_id,
            baseline_workflow_version: published.version,
            target_task_id: request.target_task_id.clone(),
            target_label: request.target_label.clone(),
            diagnosis: PipelineImprovementDiagnosis {
                primary_failure_class,
                localization_failure_classes: localization_failure_classes
                    .iter()
                    .copied()
                    .collect(),
                evidence_run_ids: request.evidence_run_ids.clone(),
                evidence_statements,
                semantic_target_correct_count,
                geometry_correction_count,
                provider_failure_count,
                no_candidate_count,
            },
            evaluation_run_ids: request.evaluation_run_ids.clone(),
            baseline_draft_id: baseline.id,
            candidate_draft_id: candidate.id,
            diff,
            validation,
            comparison: None,
            status: PipelineImprovementStatus::DraftCreated,
            setup_requirements,
            applied_draft_id: None,
            created_at: now,
            updated_at: now,
        };
        self.store.save_pipeline_improvement(&session)?;
        Ok(session)
    }

    pub fn pipeline_improvement(
        &self,
        id: PipelineImprovementId,
    ) -> Result<PipelineImprovementSession> {
        self.store
            .get_pipeline_improvement(id)?
            .ok_or_else(|| anyhow!("Pipeline improvement {id} was not found"))
    }

    pub fn project_pipeline_improvements(
        &self,
        project_id: &str,
    ) -> Result<Vec<PipelineImprovementSession>> {
        self.project_path(project_id)?;
        self.store
            .list_project_pipeline_improvements(project_id)
            .map_err(anyhow::Error::from)
    }

    pub async fn compare_pipeline_improvement(
        &self,
        id: PipelineImprovementId,
        settings: &Settings,
        policy: PipelineImprovementPolicy,
        provider_kind: &str,
        temporary_api_key: Option<&str>,
    ) -> Result<PipelineImprovementSession> {
        policy.validate().map_err(anyhow::Error::msg)?;
        let mut session = self.pipeline_improvement(id)?;
        if session.evaluation_run_ids.is_empty() {
            bail!("select independent evaluation holdout Runs before comparison");
        }
        let references = self.pipeline_improvement_references(&session)?;
        let diagnosis_indices = self.pipeline_improvement_run_image_indices(
            &session.project_id,
            &session.diagnosis.evidence_run_ids,
        )?;
        let evaluation_indices = references.keys().copied().collect::<BTreeSet<_>>();
        if !diagnosis_indices.is_disjoint(&evaluation_indices) {
            bail!("diagnosis evidence and evaluation holdout contain the same Project image");
        }
        let image_indices = references.keys().copied().take(10).collect::<Vec<_>>();
        if image_indices.is_empty() {
            bail!("evaluation Runs contain no human-accepted bounding-box references");
        }
        let baseline = self
            .dry_run_workflow_samples_with_provider(
                &session.baseline_draft_id,
                settings,
                &image_indices,
                provider_kind,
                temporary_api_key,
            )
            .await?;
        let candidate = self
            .dry_run_workflow_samples_with_provider(
                &session.candidate_draft_id,
                settings,
                &image_indices,
                provider_kind,
                temporary_api_key,
            )
            .await?;
        let baseline_metrics =
            pipeline_geometry_metrics(&baseline, &references, session.target_label.as_str());
        let candidate_metrics =
            pipeline_geometry_metrics(&candidate, &references, session.target_label.as_str());
        let comparison =
            compare_pipeline_geometry_metrics(baseline_metrics, candidate_metrics, true, policy);
        session.comparison = Some(comparison);
        session.status = PipelineImprovementStatus::AwaitingHumanApproval;
        session.updated_at = chrono::Utc::now();
        self.store.save_pipeline_improvement(&session)?;
        Ok(session)
    }

    pub fn apply_pipeline_improvement(
        &self,
        id: PipelineImprovementId,
        request: &ApplyPipelineImprovementRequest,
    ) -> Result<PipelineImprovementSession> {
        if request.selected_change_ids.is_empty() {
            bail!("select at least one reviewed change to apply");
        }
        let mut session = self.pipeline_improvement(id)?;
        if session.status != PipelineImprovementStatus::AwaitingHumanApproval {
            bail!("compare the candidate on an independent holdout before human approval");
        }
        let report = self.apply_workflow_draft_diff(
            &session.baseline_draft_id,
            &session.candidate_draft_id,
            &request.selected_change_ids,
        )?;
        session.applied_draft_id = Some(report.draft.id);
        session.status = PipelineImprovementStatus::AppliedToDraft;
        session.updated_at = chrono::Utc::now();
        self.store.save_pipeline_improvement(&session)?;
        Ok(session)
    }

    fn pipeline_improvement_references(
        &self,
        session: &PipelineImprovementSession,
    ) -> Result<BTreeMap<usize, Vec<NormalizedRect>>> {
        let project_path = self.project_path(&session.project_id)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let mut references = BTreeMap::<usize, Vec<NormalizedRect>>::new();
        for run_id in &session.evaluation_run_ids {
            let history = self.store.history(*run_id)?;
            if history.run.project_id != Some(stable_id) {
                bail!("evaluation Run {run_id} does not belong to the improvement Project");
            }
            let inspection = self.inspect_run_annotations(*run_id)?;
            let image_index = inspection.image_index.ok_or_else(|| {
                anyhow!("evaluation Run {run_id} has no recoverable Project image identity")
            })?;
            for annotation in inspection.annotations {
                if annotation.task_id == session.target_task_id
                    && annotation.label.as_ref() == Some(&session.target_label)
                    && annotation.review_status == ReviewStatus::HumanAccepted
                    && let annotagent_core::AnnotationValue::BoundingBox { rect } = annotation.value
                {
                    references.entry(image_index).or_default().push(rect);
                }
            }
        }
        Ok(references)
    }

    fn pipeline_improvement_run_image_indices(
        &self,
        project_id: &str,
        run_ids: &[RunId],
    ) -> Result<BTreeSet<usize>> {
        let project_path = self.project_path(project_id)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let mut indices = BTreeSet::new();
        for run_id in run_ids {
            let history = self.store.history(*run_id)?;
            if history.run.project_id != Some(stable_id) {
                bail!("Run {run_id} does not belong to the Pipeline improvement Project");
            }
            let index = self
                .inspect_run_annotations(*run_id)?
                .image_index
                .ok_or_else(|| {
                    anyhow!("diagnosis Run {run_id} has no recoverable Project image identity")
                })?;
            indices.insert(index);
        }
        Ok(indices)
    }

    fn geometry_calibration_key(
        &self,
        project_id: &str,
        project: &ProjectSchema,
        draft: &WorkflowDraft,
        profiles: &[ModelProfileSnapshot],
        node_id: &str,
        scope: (TaskId, Option<LabelId>),
    ) -> Result<GeometryCalibrationKey> {
        let (task_id, label_id) = scope;
        let project_path = self.project_path(project_id)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let node = draft
            .nodes
            .iter()
            .find(|node| node.id == node_id)
            .ok_or_else(|| anyhow!("calibration node {node_id:?} does not exist"))?;
        let binding = node
            .model_profile_binding
            .as_ref()
            .ok_or_else(|| anyhow!("calibration node has no revisioned Model Profile binding"))?;
        let profile = profiles
            .iter()
            .find(|profile| profile.model_profile_id == binding.model_profile_id)
            .ok_or_else(|| {
                anyhow!("calibration node Model Profile is not frozen in the Workflow")
            })?;
        let prompt_version = [
            "prompt_version",
            "prompt_template_version",
            "system_prompt_version",
        ]
        .into_iter()
        .find_map(|key| {
            node.parameters
                .get(key)
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
        })
        .or_else(|| profile.generation_defaults.system_prompt_version.clone());
        let preprocessing = draft
            .nodes
            .iter()
            .filter(|candidate| {
                candidate.id != node.id
                    && workflow_path_exists(draft, &candidate.id, &node.id)
                    && (matches!(candidate.node_type.as_str(), "core.resize" | "core.tile")
                        || candidate.parameters.keys().any(|key| {
                            key.contains("resize")
                                || key.contains("tile")
                                || key.contains("grid")
                                || key.contains("preprocess")
                        }))
            })
            .collect::<Vec<_>>();
        let refinement = draft
            .nodes
            .iter()
            .filter(|candidate| {
                candidate.id != node.id
                    && workflow_path_exists(draft, &node.id, &candidate.id)
                    && (candidate.node_type.contains("segment")
                        || candidate.node_type.contains("mask_to_bbox")
                        || candidate.node_type.contains("geometry")
                        || candidate.node_type.contains("refiner")
                        || !candidate.refiners.is_empty())
            })
            .collect::<Vec<_>>();
        let image_hashes = self
            .list_project_images(project_id)?
            .into_iter()
            .map(|path| {
                std::fs::read(&path)
                    .with_context(|| format!("cannot read calibration image {}", path.display()))
                    .map(|bytes| sha256(&bytes))
            })
            .collect::<Result<Vec<_>>>()?;
        let node_config_hash = sha256(&serde_json::to_vec(node)?);
        let preprocessing_hash = sha256(&serde_json::to_vec(&preprocessing)?);
        let refinement_hash = sha256(&serde_json::to_vec(&refinement)?);
        let label_schema_hash = sha256(&serde_json::to_vec(&project.tasks)?);
        let dataset_profile_revision = sha256(&serde_json::to_vec(&json!({
            "dataset": &project.dataset,
            "image_hashes": image_hashes,
        }))?);
        let key = GeometryCalibrationKey {
            project_id: stable_id,
            task_id,
            label_id,
            model_profile_id: profile.model_profile_id,
            model_profile_revision: profile.revision,
            node_definition_id: node.node_type.clone(),
            node_config_hash,
            prompt_version,
            preprocessing_hash,
            dataset_profile_revision,
            label_schema_hash,
            refinement_hash,
        };
        key.validate().map_err(|error| anyhow!(error))?;
        Ok(key)
    }

    fn geometry_safety_validation_context(
        &self,
        project_id: &str,
        project: &ProjectSchema,
        draft: &WorkflowDraft,
        profiles: &[ModelProfileSnapshot],
    ) -> Result<annotagent_core::GeometrySafetyValidationContext> {
        let project_path = self.project_path(project_id)?;
        let stable_id = stable_project_id(project_path.parent().unwrap_or(&self.workspace));
        let mut context =
            annotagent_core::geometry_safety_context(stable_id, project, draft, profiles);
        context.project_policies = self.project_geometry_policies(project_id)?;
        let reports = self.store.list_project_geometry_calibrations(stable_id)?;
        let node_ids = context
            .node_contracts
            .iter()
            .map(|contract| contract.node_id.clone())
            .collect::<Vec<_>>();
        for node_id in node_ids {
            let Some((task_id, label_id)) = calibration_scope_for_node(project, draft, &node_id)
            else {
                continue;
            };
            let Ok(key) = self.geometry_calibration_key(
                project_id,
                project,
                draft,
                profiles,
                &node_id,
                (task_id, label_id),
            ) else {
                continue;
            };
            let status = reports
                .iter()
                .find(|report| report.exact_key_match(&key))
                .map(|report| report.status)
                .or_else(|| {
                    reports
                        .iter()
                        .any(|report| calibration_scope_related(&report.key, &key))
                        .then_some(GeometryCalibrationStatus::Stale)
                })
                .unwrap_or(GeometryCalibrationStatus::Uncalibrated);
            context.set_calibration_status(&node_id, status);
        }
        Ok(context)
    }

    pub fn active_run_for_project(&self, project_id: ProjectId) -> Result<Option<RunId>> {
        Ok(self
            .active
            .lock()
            .map_err(|_| anyhow!("active run lock poisoned"))?
            .iter()
            .find_map(|(run_id, managed)| {
                (managed.project_id == project_id && managed.is_active()).then_some(*run_id)
            }))
    }

    pub fn is_run_controllable(&self, run_id: RunId) -> bool {
        self.active
            .lock()
            .ok()
            .and_then(|active| active.get(&run_id).cloned())
            .is_some_and(|managed| managed.is_active())
    }

    pub fn project_path(&self, project_id: &str) -> Result<PathBuf> {
        validate_project_id(project_id)?;
        let directory = self.workspace.join(project_id);
        let canonical = directory
            .canonicalize()
            .with_context(|| format!("project {project_id:?} does not exist"))?;
        ensure_within(&self.workspace, &canonical)?;
        let path = canonical.join("project.yaml");
        if !path.is_file() {
            bail!("project {project_id:?} has no project.yaml");
        }
        Ok(path)
    }

    pub fn create_project(&self, project_id: &str, yaml: &str) -> Result<ProjectSummary> {
        validate_project_id(project_id)?;
        let project = ProjectSchema::from_yaml(yaml).map_err(|error| anyhow!(error))?;
        resolve_project_skills(&project, &self.skills)?;
        let directory = self.workspace.join(project_id);
        if directory.exists() {
            bail!("project {project_id:?} already exists");
        }
        std::fs::create_dir_all(directory.join(&project.dataset.root))?;
        std::fs::write(directory.join("project.yaml"), yaml)?;
        self.get_project(project_id)
    }

    pub fn add_project_label(
        &self,
        project_id: &str,
        task_id: &str,
        label: &str,
    ) -> Result<ProjectSummary> {
        let _guard = self
            .project_schema_writes
            .lock()
            .map_err(|_| anyhow!("project schema lock poisoned"))?;
        let path = self.project_path(project_id)?;
        let (mut project, _) = load_project_schema_with_registry(&path, &self.skills)?;
        let task = project
            .tasks
            .iter_mut()
            .find(|task| task.id.as_str() == task_id)
            .ok_or_else(|| anyhow!("task {task_id:?} is not in Project Schema"))?;
        if task.labels.iter().any(|current| current == label) {
            bail!("Label {label:?} already exists on task {task_id:?}");
        }
        task.labels.push(label.to_owned());
        resolve_project_skills(&project, &self.skills)?;
        let yaml = serde_yaml::to_string(&project)?;
        std::fs::write(&path, yaml)?;
        self.get_project(project_id)
    }

    pub fn set_project_enabled_skills(
        &self,
        project_id: &str,
        enabled_skills: Vec<EnabledSkillConfig>,
    ) -> Result<ProjectSummary> {
        let _guard = self
            .project_schema_writes
            .lock()
            .map_err(|_| anyhow!("project schema lock poisoned"))?;
        let path = self.project_path(project_id)?;
        let yaml = std::fs::read_to_string(&path)?;
        let mut project = ProjectSchema::from_yaml(&yaml).map_err(|error| anyhow!(error))?;
        project.project.enabled_skills = enabled_skills;
        project.project.skill.clear();
        project.project.skill_version.clear();
        resolve_project_skills(&project, &self.skills)?;
        std::fs::write(&path, serde_yaml::to_string(&project)?)?;
        self.get_project(project_id)
    }

    pub fn add_project_task(
        &self,
        project_id: &str,
        display_name: &str,
        kind: TaskKind,
        labels: Vec<String>,
        attributes: BTreeMap<String, AttributeDefinition>,
    ) -> Result<ProjectSummary> {
        let _guard = self
            .project_schema_writes
            .lock()
            .map_err(|_| anyhow!("project schema lock poisoned"))?;
        let display_name = display_name.trim();
        if display_name.is_empty() {
            bail!("Label group display name cannot be empty");
        }
        let path = self.project_path(project_id)?;
        let (mut project, _) = load_project_schema_with_registry(&path, &self.skills)?;
        let base = display_name
            .chars()
            .map(|character| {
                if character.is_ascii_alphanumeric() {
                    character.to_ascii_lowercase()
                } else {
                    '_'
                }
            })
            .collect::<String>()
            .trim_matches('_')
            .to_owned();
        let base = if base.is_empty() {
            "label_task".to_owned()
        } else {
            base
        };
        let mut id = base.clone();
        let mut suffix = 2;
        while project.tasks.iter().any(|task| task.id.as_str() == id) {
            id = format!("{base}_{suffix}");
            suffix += 1;
        }
        project.tasks.push(TaskConfig {
            id: TaskId::new(id),
            display_name: Some(display_name.to_owned()),
            kind,
            labels,
            required: true,
            multi_label: false,
            depends_on: Vec::new(),
            validators: Vec::new(),
            refiners: Vec::new(),
            target_task: None,
            target_labels: Vec::new(),
            attributes,
        });
        resolve_project_skills(&project, &self.skills)?;
        std::fs::write(&path, serde_yaml::to_string(&project)?)?;
        self.get_project(project_id)
    }

    /// The guided goal edits the existing Schema, never a parallel workflow store.
    pub fn project_execution_schema_hash(&self, project_id: &str) -> Result<String> {
        let path = self.project_path(project_id)?;
        let (project, _) = load_project_schema_with_registry(&path, &self.skills)?;
        Ok(annotagent_image_tools::sha256(&serde_json::to_vec(
            &project,
        )?))
    }

    /// Resolve ownership through the canonical Project directory, never a client UUID.
    fn conversation_project_identity(&self, project_id: &str) -> Result<String> {
        let path = self.project_path(project_id)?;
        load_project_schema_with_registry(&path, &self.skills)?;
        Ok(stable_project_id(path.parent().unwrap_or(&self.workspace)).to_string())
    }

    pub fn create_project_conversation(&self, project_id: &str) -> Result<uuid::Uuid> {
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self.store.create_conversation(&owner)?)
    }

    /// Admitting a task only freezes a saved goal. It grants no model permission.
    pub fn begin_conversation_task(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
        input: &annotagent_storage::BeginConversationTask,
    ) -> Result<annotagent_storage::ConversationTask> {
        let _guard = self
            .project_schema_writes
            .lock()
            .map_err(|_| anyhow!("project schema lock poisoned"))?;
        let owner = self.conversation_project_identity(project_id)?;
        // A retry may recover its original snapshot after the Project has changed.
        let tasks = self.store.conversation_tasks(&owner, conversation)?;
        let existing = tasks.iter().any(|task| {
            task.input.id == input.id || task.input.source_message_id == input.source_message_id
        });
        if !existing
            && self.project_goal(project_id)?["revision"].as_str()
                != Some(input.schema_revision.as_str())
        {
            bail!("Project schema changed. Reload the saved goal before creating this task.");
        }
        Ok(self
            .store
            .begin_conversation_task(&owner, conversation, input)?)
    }

    pub fn conversation_tasks(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
    ) -> Result<Vec<annotagent_storage::ConversationTask>> {
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self.store.conversation_tasks(&owner, conversation)?)
    }

