    /// HTTP callers must validate the concrete Registry/data scope before admission.
    pub fn authorize_conversation_task_calls(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
        grant: &annotagent_storage::ConversationCallGrant,
    ) -> Result<()> {
        if !self
            .conversation_tasks(project_id, conversation)?
            .iter()
            .any(|task| task.input.id == grant.task_id)
        {
            bail!("task does not belong to this conversation");
        }
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self.store.authorize_conversation_calls(&owner, grant)?)
    }

    pub fn conversation_call_receipt(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
        task: uuid::Uuid,
        call: uuid::Uuid,
    ) -> Result<Option<annotagent_storage::ConversationCallReceipt>> {
        if !self
            .conversation_tasks(project_id, conversation)?
            .iter()
            .any(|item| item.input.id == task)
        {
            bail!("task does not belong to this conversation");
        }
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self.store.conversation_call(&owner, task, call)?)
    }

    pub fn project_conversation(&self, project_id: &str) -> Result<Option<uuid::Uuid>> {
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self.store.project_conversation(&owner)?)
    }

    /// Read an owned admission receipt without repeating a command or granting execution.
    pub fn project_conversation_send_receipt(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
        message: uuid::Uuid,
    ) -> Result<
        Option<(
            annotagent_storage::ConversationSendInput,
            annotagent_storage::ConversationSendReceipt,
        )>,
    > {
        let owner = self.conversation_project_identity(project_id)?;
        Ok(self
            .store
            .conversation_send_receipt(&owner, conversation, message)?)
    }

    /// Admit one frozen send command without granting inference or execution.
    pub fn send_project_conversation_message(
        &self,
        project_id: &str,
        conversation: uuid::Uuid,
        input: &annotagent_storage::ConversationSendInput,
    ) -> Result<annotagent_storage::ConversationSendReceipt> {
        let _guard = self
            .project_schema_writes
            .lock()
            .map_err(|_| anyhow!("project schema lock poisoned"))?;
        let owner = self.conversation_project_identity(project_id)?;
        if let Some((saved, receipt)) =
            self.store
                .conversation_send_receipt(&owner, conversation, input.message.id)?
        {
            if saved != *input {
                bail!("Send ID conflicts with its frozen task, message or schema");
            }
            return Ok(receipt);
        }
        if input.task_id.is_none()
            && self.project_goal(project_id)?["revision"].as_str()
                != Some(input.schema_revision.as_str())
        {
            bail!("Project schema changed before send admission. No message or task was saved.");
        }
        self.validate_conversation_message_selection(project_id, conversation, &input.message)?;
        Ok(self
            .store
            .send_conversation_message(&owner, conversation, input)?)
    }

    pub fn append_project_conversation_message(
        &self,
        project_id: &str,
        conversation_id: uuid::Uuid,
        input: &annotagent_storage::ConversationMessageInput,
    ) -> Result<annotagent_storage::ConversationMessage> {
        if matches!(
            input.reference,
            Some(annotagent_storage::ConversationSelectionRef::StopRequest { .. })
        ) {
            bail!(
                "Stop commands must use the explicit stop endpoint so their target snapshot is saved atomically"
            );
        }
        let owner = self.conversation_project_identity(project_id)?;
        if self
            .store
            .conversation_message(&owner, conversation_id, input.id)?
            .is_none()
        {
            self.validate_conversation_message_selection(project_id, conversation_id, input)?;
        }
        Ok(self
            .store
            .append_conversation_message(&owner, conversation_id, input)?)
    }

