    fn register_available_vision_model(
        application: &LocalApplication,
        builder: &PipelineBuilderModelRuntime,
        remote_model_id: &str,
        capabilities: impl IntoIterator<Item = ModelCapability>,
    ) -> ModelProfile {
        let mut model = builder.model.clone();
        model.id = ModelProfileId::new();
        model.display_name = remote_model_id.to_owned();
        model.remote_model_id = remote_model_id.to_owned();
        model.input_modalities = BTreeSet::from([InputModality::Text, InputModality::Image]);
        model.task_capabilities = capabilities.into_iter().collect();
        model.protocol_features.structured_output = true;
        model.protocol_features.tool_calls = true;
        application
            .store
            .save_model_profile(&model)
            .expect("Vision Model Profile");
        model
    }

    #[test]
    fn pipeline_builder_model_selection_respects_registry_priority_and_requirements() {
        let temporary = tempfile::tempdir().expect("temporary workspace");
        let application = LocalApplication::new(temporary.path()).expect("application");
        application
            .create_project("builder-selection", GENERIC_BBOX_PROJECT)
            .expect("Project");
        let global = register_pipeline_builder_model(&application, "global-builder");
        let resolved = application
            .resolve_pipeline_builder_model("builder-selection", None)
            .expect("global default");
        assert_eq!(resolved.model.id, global.model.id);
        assert_eq!(resolved.binding_source, ModelBindingSource::GlobalDefault);

        let mut project_model = global.model.clone();
        project_model.id = ModelProfileId::new();
        project_model.remote_model_id = "project-builder".to_owned();
        application
            .store
            .save_model_profile(&project_model)
            .expect("Project Model Profile");
        let project_path = application
            .project_path("builder-selection")
            .expect("Project path");
        application
            .store
            .save_project_model_binding(
                &annotagent_core::ProjectModelBinding {
                    id: annotagent_core::ModelBindingId::new(),
                    project_id: stable_project_id(project_path.parent().expect("Project root")),
                    capability: ModelCapability::TextGeneration,
                    role: ModelBindingRole::PipelineBuilder,
                    match_kind: annotagent_core::ModelBindingMatch::Role,
                    model_profile_id: project_model.id,
                    locked: true,
                    created_at: chrono::Utc::now(),
                },
                annotagent_core::BindingMutationActor::User,
            )
            .expect("Project binding");
        let resolved = application
            .resolve_pipeline_builder_model("builder-selection", None)
            .expect("Project default");
        assert_eq!(resolved.model.id, project_model.id);
        assert_eq!(resolved.binding_source, ModelBindingSource::ProjectRole);
        assert!(resolved.locked);

        let mut live_provider = application
            .store
            .get_provider_profile(global.provider.id)
            .expect("Provider Profile");
        live_provider.adapter = ProviderAdapterKind::OpenAiCompatible;
        live_provider.base_url = "https://provider.example/v1".parse().expect("URL");
        live_provider.credential_ref = Some(annotagent_core::CredentialReference {
            provider_id: live_provider.id,
            source: annotagent_core::CredentialSource::EnvironmentVariable,
            locator: "PIPELINE_BUILDER_SECRET_FIXTURE".to_owned(),
        });
        live_provider.health.status = ProviderHealthStatus::Configured;
        application
            .store
            .save_provider_profile(&live_provider)
            .expect("OpenAI-compatible Provider Profile");

        let explicit = application
            .resolve_pipeline_builder_model("builder-selection", Some(global.model.id))
            .expect("explicit selection");
        assert_eq!(explicit.model.id, global.model.id);
        assert_eq!(explicit.binding_source, ModelBindingSource::WorkflowNode);
        let config = explicit
            .openai_compatible_config()
            .expect("OpenAI-compatible runtime config");
        assert_eq!(config.model, "global-builder");
        assert_eq!(config.endpoint, "https://provider.example/v1");
        assert_eq!(config.max_output_tokens, 2_048);
        assert!(
            !serde_json::to_string(&explicit.safe_selection())
                .expect("safe selection")
                .contains("PIPELINE_BUILDER_SECRET_FIXTURE")
        );

        let mut incompatible = global.model.clone();
        incompatible.id = ModelProfileId::new();
        incompatible.remote_model_id = "no-structured-output".to_owned();
        incompatible.protocol_features.structured_output = false;
        application
            .store
            .save_model_profile(&incompatible)
            .expect("incompatible profile remains valid Registry metadata");
        let error = match application
            .resolve_pipeline_builder_model("builder-selection", Some(incompatible.id))
        {
            Ok(_) => panic!("Builder protocol requirements must fail closed"),
            Err(error) => error.to_string(),
        };
        assert!(error.contains("ToolCalls and StructuredOutput"));
    }

    #[test]
    fn direct_recovery_template_creation_binds_ready_registry_models() {
        let temporary = tempfile::tempdir().expect("temporary workspace");
        let application = LocalApplication::new(temporary.path()).expect("application");
        application
            .create_project(
                "direct-recovery-binding",
                include_str!("../../../examples/robocup/project.yaml"),
            )
            .expect("RoboCup Project");
        let builder = register_pipeline_builder_model(&application, "registry-builder");
        let qwen = register_available_vision_model(
            &application,
            &builder,
            "ready-qwen-vlm",
            [ModelCapability::VisionLanguage],
        );
        let segmenter = register_available_vision_model(
            &application,
            &builder,
            "ready-prompted-segmenter",
            [ModelCapability::PromptedSegmentation],
        );
        let mut provider = application
            .store
            .get_provider_profile(builder.provider.id)
            .expect("Provider Profile");
        provider.adapter = ProviderAdapterKind::OpenAiCompatible;
        provider.credential_ref = Some(annotagent_core::CredentialReference {
            provider_id: provider.id,
            source: annotagent_core::CredentialSource::EnvironmentVariable,
            locator: "DIRECT_TEMPLATE_BINDING_FIXTURE_KEY".to_owned(),
        });
        provider.health.status = ProviderHealthStatus::Configured;
        application
            .store
            .save_provider_profile(&provider)
            .expect("ready Provider Profile");

        let draft = application
            .create_workflow_draft_with_template(
                "direct-recovery-binding",
                &load_settings(None).expect("settings"),
                false,
                Some("robocup.ball.small-object-recovery"),
            )
            .expect("bound Recovery Draft");
        let vlm_nodes = draft
            .nodes
            .iter()
            .filter(|node| node.node_type == "vlm_detection.detect")
            .collect::<Vec<_>>();
        assert_eq!(vlm_nodes.len(), 3);
        assert!(vlm_nodes.iter().all(|node| {
            node.model_profile_binding
                .as_ref()
                .is_some_and(|binding| binding.model_profile_id == qwen.id && binding.locked)
                && node.unresolved_model_requirement.is_none()
        }));
        let segment = draft
            .nodes
            .iter()
            .find(|node| node.node_type == "capability.segment")
            .expect("Prompted Segmentation node");
        assert!(
            segment
                .model_profile_binding
                .as_ref()
                .is_some_and(|binding| {
                    binding.model_profile_id == segmenter.id && binding.locked
                })
        );
        assert!(draft.nodes.iter().all(|node| {
            node.model_binding
                .as_deref()
                .is_none_or(|binding| !binding.starts_with("mock"))
        }));
    }

    #[test]
    fn pipeline_builder_context_compaction_keeps_tool_call_groups_intact() {
        let mut messages = vec![
            ModelMessage {
                role: ModelRole::System,
                content: "policy".to_owned(),
                tool_call_id: None,
                tool_calls: Vec::new(),
            },
            ModelMessage {
                role: ModelRole::User,
                content: "project".to_owned(),
                tool_call_id: None,
                tool_calls: Vec::new(),
            },
        ];
        for index in 0..10 {
            let call_id = annotagent_core::ToolCallId::new(format!("call-{index}"));
            messages.push(ModelMessage {
                role: ModelRole::Assistant,
                content: String::new(),
                tool_call_id: None,
                tool_calls: vec![annotagent_core::ModelToolCall {
                    id: call_id.clone(),
                    name: "inspect_project".to_owned(),
                    arguments: json!({}),
                }],
            });
            messages.push(ModelMessage {
                role: ModelRole::Tool,
                content: format!("result-{index}-{}", "x".repeat(5_000)),
                tool_call_id: Some(call_id),
                tool_calls: Vec::new(),
            });
        }

        assert!(compact_pipeline_builder_messages(
            &mut messages,
            Some(1_000)
        ));
        assert_eq!(messages[0].role, ModelRole::System);
        assert_eq!(messages[1].role, ModelRole::User);
        assert!(messages.last().is_some_and(|message| {
            message.role == ModelRole::Tool && message.content.starts_with("result-9-")
        }));
        for (index, message) in messages.iter().enumerate() {
            if message.role != ModelRole::Tool {
                continue;
            }
            let assistant = messages.get(index.saturating_sub(1)).expect("Assistant");
            assert_eq!(assistant.role, ModelRole::Assistant);
            assert_eq!(assistant.tool_calls.len(), 1);
            assert_eq!(
                message.tool_call_id,
                Some(assistant.tool_calls[0].id.clone())
            );
        }
    }

    #[test]
    fn pipeline_builder_catalog_is_exact_and_provider_context_is_credential_safe() {
        let temporary = tempfile::tempdir().expect("temporary workspace");
        let application = LocalApplication::new(temporary.path()).expect("application");
        application
            .create_project("builder-tools", GENERIC_BBOX_PROJECT)
            .expect("Project");
        let provider_id = annotagent_core::ProviderId::new();
        let now = chrono::Utc::now();
        application
            .store
            .save_provider_profile(&annotagent_core::ProviderProfile {
                id: provider_id,
                display_name: "Credential-safe fixture".to_owned(),
                preset_id: None,
                adapter: ProviderAdapterKind::OpenAiCompatible,
                base_url: "https://provider.example/v1".parse().expect("URL"),
                organization: None,
                workspace: None,
                credential_ref: Some(annotagent_core::CredentialReference {
                    provider_id,
                    source: annotagent_core::CredentialSource::EnvironmentVariable,
                    locator: "ANNOTAGENT_SUPER_SECRET_FIXTURE".to_owned(),
                }),
                safe_headers: BTreeMap::new(),
                connection_policy: annotagent_core::ProviderConnectionPolicy::default(),
                enabled: true,
                health: annotagent_core::ProviderHealthSnapshot {
                    status: ProviderHealthStatus::Configured,
                    safe_message: Some("Configured".to_owned()),
                    checked_at: None,
                },
                created_at: now,
                updated_at: now,
            })
            .expect("Provider Profile");
        let settings = load_settings(None).expect("settings");
        let input = application
            .workflow_advisor_input_for_label(
                "builder-tools",
                &settings,
                WorkflowConstraints::default(),
                Some("components"),
                Some("component"),
            )
            .expect("Builder input");
        let tools = pipeline_builder_live_tools(&input);
        let names = tools
            .iter()
            .map(|tool| tool.name.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(names.len(), 72);
        assert_eq!(
            names,
            PipelineBuilderTool::ALL
                .iter()
                .map(|tool| tool.as_str())
                .collect::<BTreeSet<_>>()
        );
        for forbidden in [
            "publish_pipeline",
            "start_full_dataset_run",
            "set_api_key",
            "create_provider",
            "delete_provider",
            "execute_shell",
            "execute_python",
            "download_model",
            "install_model_bundle",
            "download_model_bundle",
            "accept_model_license",
            "import_local_bundle",
            "delete_model_bundle",
            "run_billable_probe",
            "open_arbitrary_url",
        ] {
            assert!(!names.contains(forbidden), "{forbidden}");
        }
        let encoded = serde_json::to_string(&input.provider_profiles).expect("safe Provider JSON");
        assert!(encoded.contains("Credential-safe fixture"));
        assert!(!encoded.contains("ANNOTAGENT_SUPER_SECRET_FIXTURE"));
        assert!(!encoded.contains("credential_ref"));
        assert!(!encoded.contains("locator"));

        let progress_budget = annotagent_core::PipelineBuilderBudget {
            max_total_tool_calls: 8,
            reserved_materialization_calls: 1,
            reserved_validation_calls: 1,
            reserved_finalization_calls: 3,
            max_discovery_tool_calls: 4,
            ..annotagent_core::PipelineBuilderBudget::default()
        };
        let mut session = AgentSession::start(
            AgentKind::PipelineBuilder,
            AgentBudget {
                max_steps: 8,
                max_tool_calls: 8,
                ..AgentBudget::default()
            },
        )
        .with_builder_progress(
            progress_budget,
            annotagent_core::BuilderProgressInvariant::default(),
        );
        let context_tools = pipeline_builder_visible_tools(&tools, &session);
        assert_eq!(
            context_tools
                .iter()
                .map(|tool| tool.name.as_str())
                .collect::<Vec<_>>(),
            vec![PipelineBuilderTool::GetPipelineBuilderContext.as_str()]
        );
        session
            .transition_builder_phase(
                annotagent_core::PipelineBuilderPhase::FeasibilityAnalysis,
                "Resolve feasibility",
            )
            .expect("feasibility phase");
        let feasibility_tools = pipeline_builder_visible_tools(&tools, &session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::ResolvePipelineFeasibility.as_str())
        );
        assert!(feasibility_tools.contains(PipelineBuilderTool::InspectModelsBatch.as_str()));
        assert!(feasibility_tools.contains(PipelineBuilderTool::ListReadyModels.as_str()));
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::ListCompatibleModelBundles.as_str())
        );
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::InspectModelBundleSummary.as_str())
        );
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::InspectModelQualityContract.as_str())
        );
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::InspectProjectGeometryPolicy.as_str())
        );
        assert!(
            feasibility_tools
                .contains(PipelineBuilderTool::InspectGeometryCorrectionSummary.as_str())
        );
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::InspectGeometryCalibration.as_str())
        );
        assert!(
            feasibility_tools.contains(PipelineBuilderTool::FindGeometryRefinementPath.as_str())
        );
        assert!(!feasibility_tools.contains(PipelineBuilderTool::InspectModelProfile.as_str()));
        let mut candidate_session = session.clone();
        candidate_session
            .transition_builder_phase(
                annotagent_core::PipelineBuilderPhase::CandidateSelection,
                "Runtime selects a persisted Candidate",
            )
            .expect("candidate selection phase");
        assert!(pipeline_builder_visible_tools(&tools, &candidate_session).is_empty());
        session
            .transition_builder_phase(
                annotagent_core::PipelineBuilderPhase::Drafting,
                "Persist Draft",
            )
            .expect("draft phase");
        let drafting_tools = pipeline_builder_visible_tools(&tools, &session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(drafting_tools.contains(PipelineBuilderTool::CreateDraftFromTemplate.as_str()));
        let resolving_session =
            session
                .clone()
                .with_build_mode(annotagent_core::PipelineBuildMode::ResolveBindings {
                    draft_id: "blocked-draft".to_owned(),
                });
        let resolving_tools = pipeline_builder_visible_tools(&tools, &resolving_session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(resolving_tools.contains(PipelineBuilderTool::BindModelProfile.as_str()));
        assert!(resolving_tools.contains(PipelineBuilderTool::ValidatePipeline.as_str()));
        assert!(
            !resolving_tools.contains(PipelineBuilderTool::FindArtifactConversionPath.as_str())
        );
        assert!(
            !resolving_tools.contains(PipelineBuilderTool::FindGeometryRefinementPath.as_str())
        );
        assert!(!resolving_tools.contains(PipelineBuilderTool::CreateDraftFromTemplate.as_str()));
        assert!(!resolving_tools.contains(PipelineBuilderTool::AddPipelineNode.as_str()));
        assert!(!resolving_tools.contains(PipelineBuilderTool::RemovePipelineNode.as_str()));
        session
            .transition_builder_phase(
                annotagent_core::PipelineBuilderPhase::Validating,
                "Validate persisted Draft",
            )
            .expect("validation phase");
        let validation_tools = pipeline_builder_visible_tools(&tools, &session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(validation_tools.contains(PipelineBuilderTool::ValidatePipeline.as_str()));
        assert!(!validation_tools.contains(PipelineBuilderTool::CreatePipelineDraft.as_str()));
        assert!(!validation_tools.contains(PipelineBuilderTool::CreateDraftFromTemplate.as_str()));
        assert!(!validation_tools.contains(PipelineBuilderTool::CreateBlockedDraft.as_str()));
        let mut planning_session = session.clone();
        planning_session.builder_constraints = Some(PipelineBuilderConstraints {
            maximum_dry_runs: 0,
            ..PipelineBuilderConstraints::default()
        });
        let planning_tools = pipeline_builder_visible_tools(&tools, &planning_session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(!planning_tools.contains(PipelineBuilderTool::DryRunPipeline.as_str()));
        assert!(planning_tools.contains(PipelineBuilderTool::SubmitDraftForHumanApproval.as_str()));
        assert!(planning_tools.contains(PipelineBuilderTool::ValidatePipeline.as_str()));
        for index in 0..5 {
            session
                .record_tool("bounded_test", json!({"index": index}), json!({}), true)
                .expect("bounded Tool Call");
        }
        let reserve_tools = pipeline_builder_visible_tools(&tools, &session)
            .into_iter()
            .map(|tool| tool.name)
            .collect::<BTreeSet<_>>();
        assert!(reserve_tools.contains(PipelineBuilderTool::CreateBlockedDraft.as_str()));
        assert!(reserve_tools.contains(PipelineBuilderTool::FinishWithSetupRequirements.as_str()));
        assert!(!reserve_tools.contains(PipelineBuilderTool::InspectModelsBatch.as_str()));
        assert_eq!(session.total_tool_calls, 5);
        assert_eq!(session.remaining_tool_calls, 3);
        assert_eq!(session.reserved_finalization_calls, 3);
    }

    #[tokio::test]
    async fn pipeline_builder_profile_binding_runtime_policy_and_undo_persist_real_draft() {
        let temporary = tempfile::tempdir().expect("temporary workspace");
        let application = LocalApplication::new(temporary.path()).expect("application");
        application
            .create_project("builder-mutations", GENERIC_CLASSIFICATION_PROJECT)
            .expect("Project");
        let settings = load_settings(None).expect("settings");
        let provider_id = annotagent_core::ProviderId::new();
        let now = chrono::Utc::now();
        application
            .store
            .save_provider_profile(&annotagent_core::ProviderProfile {
                id: provider_id,
                display_name: "Offline Builder Provider".to_owned(),
                preset_id: Some("mock".to_owned()),
                adapter: ProviderAdapterKind::Mock,
                base_url: "https://mock.invalid/v1".parse().expect("URL"),
                organization: None,
                workspace: None,
                credential_ref: None,
                safe_headers: BTreeMap::new(),
                connection_policy: annotagent_core::ProviderConnectionPolicy::default(),
                enabled: true,
                health: annotagent_core::ProviderHealthSnapshot {
                    status: ProviderHealthStatus::Available,
                    safe_message: Some("Offline fixture".to_owned()),
                    checked_at: Some(now),
                },
                created_at: now,
                updated_at: now,
            })
            .expect("Provider Profile");
        let model_profile = ModelProfile {
            id: annotagent_core::ModelProfileId::new(),
            revision: 1,
            provider_id,
            display_name: "Offline classifier".to_owned(),
            remote_model_id: settings.provider.model.clone(),
            input_modalities: BTreeSet::from([
                annotagent_core::InputModality::Text,
                annotagent_core::InputModality::Image,
            ]),
            protocol_features: annotagent_core::ProtocolFeatures::default(),
            task_capabilities: BTreeSet::from([ModelCapability::ImageClassification]),
            capability_source: annotagent_core::CapabilityDeclarationSource::UserDeclared,
            limits: annotagent_core::ModelLimits::default(),
            generation_defaults: annotagent_core::GenerationDefaults::default(),
            pricing: annotagent_core::ModelPricing::default(),
            quality_contracts: Vec::new(),
            status: ModelProfileStatus::Available,
            enabled: true,
            locked: false,
            created_at: now,
            updated_at: now,
        };
        application
            .store
            .save_model_profile(&model_profile)
            .expect("Model Profile");
        let constraints = WorkflowConstraints::default();
        let input = application
            .workflow_advisor_input_for_label(
                "builder-mutations",
                &settings,
                constraints.clone(),
                Some("scene"),
                Some("day"),
            )
            .expect("Builder input");
        let safe = application
            .suggest_label_pipeline_preview(
                "builder-mutations",
                &settings,
                "scene",
                "day",
                &constraints,
            )
            .expect("safe Draft");
        let scripted_step = |name: &str, arguments: serde_json::Value| MockStep {
            expect_task: Some("pipeline_builder".to_owned()),
            expect_message_contains: None,
            response: MockResponseSpec::ToolCall {
                name: name.to_owned(),
                arguments,
            },
            usage: MockUsage {
                input_tokens: 0,
                output_tokens: 0,
            },
        };
        let provider = MockVisionProvider::new(MockScript {
            steps: vec![
                scripted_step("inspect_project", json!({})),
                scripted_step("inspect_label", json!({})),
                scripted_step("list_enabled_skills", json!({})),
                scripted_step("list_node_definitions", json!({})),
                scripted_step(
                    "list_compatible_models",
                    json!({"node_type": "capability.classify"}),
                ),
                scripted_step(
                    "create_pipeline_draft",
                    json!({"name": "Agent mutation fixture"}),
                ),
                scripted_step(
                    "add_pipeline_node",
                    json!({"node_type": "core.image_input", "node_id": "image", "configuration": {}}),
                ),
                scripted_step(
                    "add_pipeline_node",
                    json!({"node_type": "capability.classify", "node_id": "classifier", "configuration": {"labels": ["day", "night"]}}),
                ),
                scripted_step(
                    "bind_model_profile",
                    json!({"node_id": "classifier", "model_profile_id": model_profile.id, "locked": true}),
                ),
                scripted_step(
                    "set_runtime_policy",
                    json!({"policy_id": "retry", "configuration": {"maximum_attempts": 2}}),
                ),
                scripted_step("undo_last_draft_change", json!({})),
            ],
        });
        let report = Box::pin(application.run_workflow_advisor_with_provider(
            "builder-mutations",
            &settings,
            &constraints,
            Some(("scene", "day")),
            input,
            safe,
            &provider,
            PipelineBuilderConstraints::default(),
            CancellationToken::new(),
        ))
        .await
        .expect("bounded Builder loop");
        let suggestion = report.suggestion.expect("persisted Draft suggestion");
        let persisted = application
            .store
            .get_workflow_draft(&suggestion.draft.id)
            .expect("persisted Draft");
        assert_eq!(persisted.name, "Agent mutation fixture");
        assert_eq!(persisted.nodes.len(), 2);
        assert!(
            persisted.runtime_policies.is_empty(),
            "undo restored Runtime Policy"
        );
        let classifier = persisted
            .nodes
            .iter()
            .find(|node| node.id == "classifier")
            .expect("classifier node");
        assert_eq!(
            classifier
                .model_profile_binding
                .as_ref()
                .map(|binding| (binding.model_profile_id, binding.locked)),
            Some((model_profile.id, true))
        );
        assert_eq!(classifier.model_binding.as_deref(), Some("default-vision"));
        assert!(
            application
                .store
                .list_published_workflow_versions(Some("builder-mutations"))
                .expect("published versions")
                .is_empty()
        );
        assert!(application.list_runs().expect("formal Runs").is_empty());
    }

