    #[test]
    fn image_import_reports_quality_and_supports_removing_project_copy() {
        let temp = tempfile::tempdir().expect("temp");
        let workspace = temp.path().join("workspace");
        let app = LocalApplication::new(&workspace).expect("app");
        app.create_project("generic", GENERIC_PROJECT)
            .expect("project");
        let incoming = workspace.join("incoming");
        std::fs::create_dir_all(&incoming).expect("incoming");
        annotagent_image_tools::generate_synthetic_inspection(&incoming.join("valid.png"))
            .expect("valid image");
        std::fs::copy(incoming.join("valid.png"), incoming.join("duplicate.png"))
            .expect("duplicate");
        std::fs::write(incoming.join("corrupt.png"), b"not an image").expect("corrupt fixture");
        std::fs::write(incoming.join("notes.txt"), b"ignore me").expect("unsupported fixture");

        let report = app
            .import_images_with_report("generic", &incoming)
            .expect("import report");
        assert_eq!(report.discovered, 3);
        assert_eq!(report.imported, 1);
        assert_eq!(report.duplicates, 1);
        assert_eq!(report.corrupt.len(), 1);
        assert_eq!(report.unsupported_files, 1);
        assert_eq!(app.list_project_images("generic").expect("images").len(), 1);

        let removed = app
            .remove_project_image("generic", 0)
            .expect("remove image");
        assert!(
            Path::new(&removed)
                .extension()
                .is_some_and(|extension| extension.eq_ignore_ascii_case("png"))
        );
        assert!(
            app.list_project_images("generic")
                .expect("images")
                .is_empty()
        );
    }

    #[tokio::test]
    async fn human_annotation_rejects_foreign_image_even_when_run_has_no_annotations() {
        let temp = tempfile::tempdir().expect("temp");
        let workspace = temp.path().join("workspace");
        let app = LocalApplication::new(&workspace).expect("app");
        app.create_project("generic", GENERIC_PROJECT)
            .expect("project");
        let run_id = RunId::new();
        let project_path = app.project_path("generic").expect("project path");
        app.store()
            .create_run(&RunRecord {
                id: run_id,
                project_id: stable_project_id(project_path.parent().expect("project root")),
                project_name: "Generic inspection".to_owned(),
                skill_id: "none".to_owned(),
                provider: "core".to_owned(),
                model: "none".to_owned(),
                status: RunStatus::Pending,
                project_schema_json: "{}".to_owned(),
                workflow_snapshot_json: None,
            })
            .await
            .expect("create empty run");
        let annotation = Annotation {
            id: AnnotationId::new(),
            image_id: ImageId::new(),
            task_id: TaskId::from("objects"),
            label: Some(LabelId::from("ball")),
            value: AnnotationValue::BoundingBox {
                rect: NormalizedRect::new(0.1, 0.1, 0.2, 0.2).expect("bbox"),
            },
            attributes: BTreeMap::new(),
            confidence: None,
            source: AnnotationSource::Human,
            review_status: ReviewStatus::Draft,
            provenance: AnnotationProvenance::default(),
            created_at: chrono::Utc::now(),
        };

        let error = app
            .create_human_annotation(run_id, annotation.clone())
            .await
            .expect_err("foreign image must be rejected");
        assert!(error.to_string().contains("does not belong to this Run"));
        app.store()
            .register_run_image(run_id, annotation.image_id, "completed")
            .unwrap();
        let first = app
            .create_human_annotation(run_id, annotation.clone())
            .await
            .unwrap();
        let retry = app
            .create_human_annotation(run_id, annotation.clone())
            .await
            .unwrap();
        assert_eq!(retry, first);
        assert_eq!(first.review_status, ReviewStatus::NeedsReview);
        assert!(first.confidence.is_none());
        assert_eq!(app.store().list_annotations(run_id).unwrap().len(), 1);
        let mut conflicting = annotation.clone();
        conflicting.label = Some(LabelId::from("different"));
        assert!(
            app.create_human_annotation(run_id, conflicting)
                .await
                .unwrap_err()
                .to_string()
                .contains("different content")
        );
        let mut invalid = annotation;
        invalid.id = AnnotationId::new();
        invalid.value = AnnotationValue::Classification { labels: vec![] };
        assert!(app.create_human_annotation(run_id, invalid).await.is_err());
        assert_eq!(app.store().list_annotations(run_id).unwrap().len(), 1);
    }

    #[test]
    fn unified_send_freezes_task_and_checks_schema_without_execution() {
        let temporary = tempfile::tempdir().unwrap();
        let app = LocalApplication::new(temporary.path()).unwrap();
        let yaml = "version: 1\nproject:\n  name: TEST send\ndataset:\n  root: images\nruntime: {}\ntasks: []\nreview:\n  auto_accept_confidence: 0.9\n  force_review_below: 0.5\nexport:\n  formats: [native]\n";
        app.create_project("TEST-send", yaml).unwrap();
        app.create_project("TEST-other", yaml).unwrap();
        let conversation = app.create_project_conversation("TEST-send").unwrap();
        let mut command = annotagent_storage::ConversationSendInput {
            message: annotagent_storage::ConversationMessageInput {
                id: uuid::Uuid::new_v4(),
                text: "TEST cups".into(),
                image: None,
                reference: None,
            },
            task_id: None,
            schema_revision: "0".repeat(64),
        };
        assert!(
            app.send_project_conversation_message("TEST-send", conversation, &command)
                .is_err()
        );
        assert!(
            app.project_conversation_messages("TEST-send", conversation, 0, 100)
                .unwrap()
                .is_empty()
        );
        command.schema_revision = app.project_goal("TEST-send").unwrap()["revision"]
            .as_str()
            .unwrap()
            .into();
        let receipt = app
            .send_project_conversation_message("TEST-send", conversation, &command)
            .unwrap();
        assert_eq!(
            app.send_project_conversation_message("TEST-send", conversation, &command)
                .unwrap(),
            receipt
        );
        assert_eq!(
            app.conversation_tasks("TEST-send", conversation)
                .unwrap()
                .len(),
            1
        );
        assert!(
            app.send_project_conversation_message("TEST-other", conversation, &command)
                .is_err()
        );
        let mut conflict = command.clone();
        conflict.schema_revision = "b".repeat(64);
        assert!(
            app.send_project_conversation_message("TEST-send", conversation, &conflict)
                .is_err()
        );
        let mut stop = command;
        stop.message.id = uuid::Uuid::new_v4();
        stop.message.reference = Some(annotagent_storage::ConversationSelectionRef::StopRequest {
            task_id: Some(receipt.task_id),
        });
        assert!(
            app.send_project_conversation_message("TEST-send", conversation, &stop)
                .is_err()
        );
        assert_eq!(
            app.project_conversation_messages("TEST-send", conversation, 0, 100)
                .unwrap()
                .len(),
            1
        );
    }

    #[test]
    fn conversation_commands_resolve_owner_and_restore_without_execution() {
        let temporary = tempfile::tempdir().unwrap();
        let app = LocalApplication::new(temporary.path()).unwrap();
        let yaml = "version: 1\nproject:\n  name: TEST conversation\ndataset:\n  root: images\nruntime: {}\ntasks: []\nreview:\n  auto_accept_confidence: 0.9\n  force_review_below: 0.5\nexport:\n  formats: [native]\n";
        app.create_project("conversation-a", yaml).unwrap();
        app.create_project("conversation-b", yaml).unwrap();
        assert!(app.create_project_conversation("missing").is_err());
        assert!(app.create_project_conversation("../outside").is_err());
        let id = app.create_project_conversation("conversation-a").unwrap();
        assert_eq!(
            id,
            app.create_project_conversation("conversation-a").unwrap()
        );
        let input = annotagent_storage::ConversationMessageInput {
            reference: None,
            id: uuid::Uuid::new_v4(),
            text: "Find cups, not bottles".into(),
            image: None,
        };
        let saved = app
            .append_project_conversation_message("conversation-a", id, &input)
            .unwrap();
        let revision = app.project_goal("conversation-a").unwrap()["revision"]
            .as_str()
            .unwrap()
            .to_owned();
        let task_input = annotagent_storage::BeginConversationTask {
            id: uuid::Uuid::new_v4(),
            source_message_id: input.id,
            schema_revision: revision.clone(),
        };
        let mut stale = task_input.clone();
        stale.schema_revision = "a".repeat(64);
        assert!(
            app.begin_conversation_task("conversation-a", id, &stale)
                .is_err()
        );
        let task = app
            .begin_conversation_task("conversation-a", id, &task_input)
            .unwrap();
        assert_eq!(
            app.begin_conversation_task("conversation-a", id, &task_input)
                .unwrap(),
            task
        );
        assert!(
            app.begin_conversation_task("conversation-b", id, &task_input)
                .is_err()
        );
        assert_eq!(
            saved,
            app.append_project_conversation_message("conversation-a", id, &input)
                .unwrap()
        );
        assert!(
            app.append_project_conversation_message("conversation-b", id, &input)
                .is_err()
        );
        assert!(
            app.project_conversation_messages("conversation-b", id, 0, 10)
                .is_err()
        );
        let restarted = LocalApplication::new(temporary.path()).unwrap();
        assert_eq!(
            restarted.conversation_tasks("conversation-a", id).unwrap(),
            vec![task.clone()]
        );
        assert_eq!(
            restarted
                .project_conversation_messages("conversation-a", id, 0, 10)
                .unwrap(),
            vec![saved]
        );
        assert!(
            restarted
                .get_project("conversation-a")
                .unwrap()
                .annotation_schema
                .is_empty()
        );
        restarted
            .save_project_goal(
                "conversation-a",
                &revision,
                "Find cups",
                TaskKind::BoundingBox,
                vec!["cup".into()],
            )
            .unwrap();
        // Existing admission remains recoverable after a schema edit; a fresh goal
        // must bind the new revision. Recovery does not imply permission to execute it.
        assert_eq!(
            restarted
                .begin_conversation_task("conversation-a", id, &task_input)
                .unwrap(),
            task
        );
        let message = annotagent_storage::ConversationMessageInput {
            reference: None,
            id: uuid::Uuid::new_v4(),
            text: "Find bottles".into(),
            image: None,
        };
        restarted
            .append_project_conversation_message("conversation-a", id, &message)
            .unwrap();
        assert!(
            restarted
                .begin_conversation_task(
                    "conversation-a",
                    id,
                    &annotagent_storage::BeginConversationTask {
                        id: uuid::Uuid::new_v4(),
                        source_message_id: message.id,
                        ..task_input
                    }
                )
                .is_err()
        );
    }

    #[test]
    fn guided_goal_preserves_multiple_labels_and_rejects_stale_and_complex_edits() {
        let temporary = tempfile::tempdir().unwrap();
        let app = LocalApplication::new(temporary.path()).unwrap();
        app.create_project("goal-test", "version: 1\nproject:\n  name: Test only\ndataset:\n  root: images\nruntime: {}\ntasks: []\nreview:\n  auto_accept_confidence: 0.9\n  force_review_below: 0.5\nexport:\n  formats: [native]\n").unwrap();
        let before = app.project_goal("goal-test").unwrap();
        let saved = app
            .save_project_goal(
                "goal-test",
                before["revision"].as_str().unwrap(),
                "Cups and plates, not bottles",
                TaskKind::BoundingBox,
                vec!["cup".into(), "plate".into()],
            )
            .unwrap();
        assert_eq!(saved["labels"], json!(["cup", "plate"]));
        assert_eq!(
            app.get_project("goal-test")
                .unwrap()
                .annotation_schema
                .len(),
            1
        );
        assert!(
            app.save_project_goal(
                "goal-test",
                before["revision"].as_str().unwrap(),
                "stale",
                TaskKind::Classification,
                vec!["wrong".into()]
            )
            .is_err()
        );
        assert_eq!(app.project_goal("goal-test").unwrap(), saved);
        let restarted = LocalApplication::new(temporary.path()).unwrap();
        assert_eq!(restarted.project_goal("goal-test").unwrap(), saved);
        app.add_project_task(
            "goal-test",
            "Other user task",
            TaskKind::Classification,
            vec!["other".into()],
            BTreeMap::new(),
        )
        .unwrap();
        let complex = app.project_goal("goal-test").unwrap();
        assert_eq!(complex["editable"], false);
        assert!(
            app.save_project_goal(
                "goal-test",
                complex["revision"].as_str().unwrap(),
                "overwrite",
                TaskKind::BoundingBox,
                vec!["bad".into()]
            )
            .is_err()
        );
        assert_eq!(
            app.get_project("goal-test")
                .unwrap()
                .annotation_schema
                .len(),
            2
        );
    }

